/*
 * OCR Gateway GCSE Chemistry A (J248) — Exam Practice Question Bank
 * Shape: { topicId: { name, questions: [{ q, marks, command, markScheme, diagram? }] } }
 * Topic ids unchanged so topics-config.js still matches.
 *
 * WHY THIS SHAPE. Real OCR Gateway GCSE Chemistry A (J248) questions are
 * context-led: a student's investigation, a real-world application, a table of
 * results or a described graph opens each question, practicals are examined in
 * context, and maths skills run throughout. Every item here follows that
 * pattern, written at both Foundation-overlap and Higher demand.
 *
 * TARIFFS. Part tariffs follow the real mix taken from the site's own past-paper
 * data for this specification.
 *
 * MARK SCHEMES. Board style: one marking point per line with (1), allow / ignore
 * / do not accept notes, max n; 6-mark extended responses use the board's three-
 * level ladder with indicative content.
 *
 * Data marked "written for this practice question" is invented but realistic and
 * every calculation has been checked.
 * Drawing canvas flag (diagram: true) enables the sketch area in practice.html.
 */

const CHEMISTRY_OCR_A_GCSE_PRACTICE = {
  'C1': {
    name: 'Particles',
    questions: [
      { q: `A student heats some ice in a beaker and measures the temperature every minute. The temperature rises from −10 °C to 0 °C, stays at 0 °C for 4 minutes, rises to 100 °C, and then stays at 100 °C.\n\nName the change of state that happens while the temperature stays at 100 °C.`, marks: 1, command: 'Name', markScheme: `• Boiling (1)\nAllow: evaporating / liquid to gas\nDo not allow: condensing / melting` },
      { q: `Solid carbon dioxide is called "dry ice". It is used to make a fog effect on stage. At room temperature it turns straight from a solid into a gas without becoming a liquid.\n\nWhat is the name of this change of state?`, marks: 1, command: 'Name', markScheme: `• Sublimation / subliming (1)\nIgnore: evaporation` },
      { q: `A scanning tunnelling microscope can produce images of individual atoms on the surface of a metal.\n\nTick (✓) one box to show the typical radius of an atom.\n\n☐ 1 × 10⁻⁴ m\n☐ 1 × 10⁻⁷ m\n☐ 1 × 10⁻¹⁰ m\n☐ 1 × 10⁻¹⁵ m`, marks: 1, command: 'Tick', markScheme: `• 1 × 10⁻¹⁰ m only ticked (1)\nIf more than one box is ticked, 0 marks.` },
      { q: `In 1932 James Chadwick carried out experiments which showed that the nucleus contains a particle with about the same mass as a proton.\n\nState the relative charge of this particle.`, marks: 1, command: 'State', markScheme: `• 0 / zero / no charge (1)\nAllow: neutral\nIgnore: naming the particle as the neutron` },
      { q: `An atom of fluorine has 9 protons, 10 neutrons and 9 electrons.\n\nWhat is the mass number of this atom?`, marks: 1, command: 'What', markScheme: `• 19 (1)\nDo not allow: 28 (electrons added) / 9` },
      { q: `A teacher puts a few drops of perfume in one corner of a classroom. A few minutes later, students on the other side of the room can smell the perfume.\n\nWhich word describes the movement of the perfume particles in the air?\n\nPut a ring around the correct answer.\n\nordered        random        stationary        vibrating`, marks: 1, command: 'Choose', markScheme: `• random (1)\nIf more than one answer is ringed, 0 marks.` },
      { q: `The table shows the melting points and boiling points of four substances (data from published tables).\n\nSubstance | Melting point (°C) | Boiling point (°C)\noxygen | −218 | −183\nbromine | −7 | 59\nmercury | −39 | 357\nsodium chloride | 801 | 1413\n\nRoom temperature is 20 °C.\n\nWhich substance is a gas at room temperature, and which substance is a solid at room temperature?`, marks: 2, command: 'Which', markScheme: `• Gas: oxygen (1)\n• Solid: sodium chloride (1)` },
      { q: `The table shows the melting point and boiling point of ethanol.\n\nMelting point: −114 °C\nBoiling point: 78 °C\n\nA sample of ethanol is cooled from 20 °C to −150 °C.\n\nDescribe the changes of state that happen to the ethanol, and give the temperature at which each happens.`, marks: 2, command: 'Describe', markScheme: `• Ethanol starts as a liquid (at 20 °C) and freezes / solidifies (1)\n• at −114 °C (1)\nAllow: liquid → solid at −114 °C for both marks\nDo not allow: any mention of boiling or condensing at 78 °C (ethanol is already below 78 °C)` },
      { q: `A student pushes the plunger of a sealed syringe. When the syringe contains air, the plunger moves in a long way. When the syringe contains water, the plunger hardly moves.\n\nExplain these observations using the particle model.`, marks: 2, command: 'Explain', markScheme: `• Particles in a gas / air are far apart / have large spaces between them, so they can be pushed closer together (1)\n• Particles in a liquid / water are already close together / touching, so there is very little space to remove (1)\nIgnore: particles getting smaller` },
      { q: `A student draws a diagram of the particles in a sample of liquid water in a beaker.\n\nDraw a diagram of the particles in a sample of steam (water as a gas). Use circles to represent the particles.`, marks: 2, command: 'Draw', diagram: true, markScheme: `• At least five circles, all the same size (1)\n• Circles are far apart / not touching, randomly arranged (1)\nDo not allow: circles touching each other or in a regular pattern for the second mark` },
      { q: `A student puts 50.0 g of ice cubes in a sealed flask and weighs the flask. The ice melts. The student weighs the flask again.\n\nThe mass has not changed.\n\nExplain why, in terms of particles.`, marks: 2, command: 'Explain', markScheme: `• Melting is a physical change / no new substance is made (1)\n• The same number of (water) particles / molecules are present, they are just arranged differently / move more (1)\nAllow: no particles enter or leave the flask (as it is sealed) for the second mark` },
      { q: `A student heats some candle wax until it melts and then lets it cool so it turns solid again. The student then burns some candle wax, and carbon dioxide and water are produced.\n\nExplain which of these is a physical change and which is a chemical change.`, marks: 2, command: 'Explain', markScheme: `• Melting / solidifying the wax is a physical change because no new substance is made / it can be reversed easily (1)\n• Burning the wax is a chemical change because new substances (carbon dioxide and water) are made / the atoms are rearranged into new molecules (1)` },
      { q: `A student heats a solid. The temperature of the solid stays the same while it is melting, even though it is still being heated.\n\nExplain why the temperature stays the same while the solid melts.`, marks: 2, command: 'Explain', markScheme: `• The energy (supplied) is used to overcome / break the forces of attraction between the particles (1)\n• So the energy does not increase the kinetic energy of the particles / the particles do not move faster (1)\nDo not allow: bonds within molecules / covalent bonds breaking` },
      { q: `In the simple particle model, particles are drawn as small, solid, inelastic spheres.\n\nWater boils at 100 °C but ethanol boils at 78 °C.\n\nExplain why the simple particle model cannot explain this difference.`, marks: 2, command: 'Explain', markScheme: `• The model does not show / include the forces between particles (1)\n• The boiling point depends on the strength of the forces between the particles, which are different for water and ethanol (1)\nAllow: the model treats all particles as the same / identical spheres for the first mark` },
      { q: `In 1904 J.J. Thomson suggested the "plum pudding" model of the atom. He had already discovered the electron.\n\nDescribe the plum pudding model of the atom.`, marks: 2, command: 'Describe', markScheme: `• A sphere / ball of positive charge (1)\n• With (negative) electrons embedded / scattered in it (1)\nIgnore: references to a nucleus\nDo not allow: electrons in shells / orbits` },
      { q: `In 1913 Niels Bohr changed Rutherford's nuclear model of the atom.\n\nDescribe the change that Bohr made to the model.`, marks: 2, command: 'Describe', markScheme: `• Electrons are in shells / orbits / energy levels (1)\n• At fixed / specific distances from the nucleus (1)\nIgnore: references to protons and neutrons` },
      { q: `John Dalton described atoms as tiny, solid spheres that could not be divided into anything smaller. This model was later replaced.\n\nGive two reasons why scientists replaced Dalton's model of the atom.`, marks: 2, command: 'Give', markScheme: `Any two from:\n• The electron was discovered / atoms were shown to contain smaller (subatomic) particles (1)\n• Alpha particle scattering showed atoms have a small, dense, positive nucleus / are mostly empty space (1)\n• New experimental evidence could not be explained by the old model (1)\nMax 2` },
      { q: `The table shows information about two ions (data written for this practice question).\n\nIon | Number of protons | Number of neutrons | Number of electrons\nMg²⁺ | 12 | 12 | ?\nF⁻ | 9 | ? | 10\n\nThe mass number of this fluoride ion is 19.\n\nComplete the table by giving the missing numbers.`, marks: 2, command: 'Complete', markScheme: `• Mg²⁺ electrons = 10 (1)\n• F⁻ neutrons = 10 (1)` },
      { q: `Carbon has two naturally occurring isotopes that are often written as carbon-12 and carbon-14. Carbon-14 is used to find the age of ancient wooden objects.\n\nThe atomic number of carbon is 6.\n\nExplain why carbon-12 and carbon-14 are isotopes of the same element.`, marks: 2, command: 'Explain', markScheme: `• Both have the same number of protons / 6 protons / same atomic number (1)\n• But a different number of neutrons: carbon-12 has 6 neutrons and carbon-14 has 8 neutrons (1)` },
      { q: `Hydrogen has three isotopes: hydrogen-1, hydrogen-2 (deuterium) and hydrogen-3 (tritium). All three react with oxygen to form water.\n\nExplain why the isotopes of hydrogen have the same chemical reactions.`, marks: 2, command: 'Explain', markScheme: `• They have the same number of electrons / same electronic structure (1)\n• Chemical reactions involve (outer) electrons, and the different number of neutrons does not affect this (1)` },
      { q: `An atom of sodium contains 11 protons, 12 neutrons and 11 electrons.\n\nExplain why the sodium atom has no overall charge.`, marks: 2, command: 'Explain', markScheme: `• It has the same number of protons and electrons / 11 protons and 11 electrons (1)\n• Protons have a charge of +1 and electrons have a charge of −1, so the charges cancel (1)\nIgnore: neutrons have no charge` },
      { q: `A gold atom has a radius of about 1.4 × 10⁻¹⁰ m. The radius of a gold nucleus is about 7.0 × 10⁻¹⁵ m.\n\nCalculate how many times larger the radius of the gold atom is than the radius of its nucleus.\n\nGive your answer in standard form.`, marks: 2, command: 'Calculate', markScheme: `• (1.4 × 10⁻¹⁰) ÷ (7.0 × 10⁻¹⁵) (1)\n• = 2 × 10⁴ (1)\nAllow: 2.0 × 10⁴\nAward 1 mark for 20 000 (not in standard form)` },
      { q: `A buckminsterfullerene (C₆₀) molecule has a diameter of about 1.0 nanometre (nm) (value written for this practice question).\n\n1 nm = 1 × 10⁻⁹ m\n\nA typical atom has a radius of about 1 × 10⁻¹⁰ m.\n\nCalculate how many times larger the diameter of the C₆₀ molecule is than the radius of a typical atom.`, marks: 2, command: 'Calculate', markScheme: `• Diameter of molecule = 1.0 × 10⁻⁹ m (1)\n• (1.0 × 10⁻⁹) ÷ (1 × 10⁻¹⁰) = 10 (1)\nAllow: 10 times / one order of magnitude for 2 marks` },
      { q: `A student is asked to identify an atom. The student is told that the atom has 20 protons and 20 neutrons.\n\nUse the Periodic Table to name the element and write the symbol for this atom showing its mass number and atomic number.`, marks: 2, command: 'Write', markScheme: `• Calcium (1)\n• ⁴⁰₂₀Ca (1)\nAllow: mass number 40 at top left and atomic number 20 at bottom left\nDo not allow: ²⁰₄₀Ca` },
      { q: `A student writes this statement about ions:\n\n"A sodium atom becomes a positive ion, Na⁺, by gaining a proton."\n\nExplain why the student is wrong.`, marks: 2, command: 'Explain', markScheme: `• The number of protons / nucleus does not change when an ion forms (1)\n• The sodium atom loses an electron (so there is one more proton than electrons) (1)` },
      { q: `A student calculates the mass number of an atom of chlorine by adding together the numbers of protons and neutrons. The student does not include the electrons.\n\nExplain why the electrons are not included in the mass number.`, marks: 2, command: 'Explain', markScheme: `• Electrons have a very small mass / relative mass of about 1/1840 / 0.0005 (1)\n• Compared with protons and neutrons, which each have a relative mass of 1 (so electrons make almost no difference to the mass) (1)\nAllow: almost all the mass is in the nucleus for the second mark` },
      { q: `On a cold day, water droplets form on the inside of a car windscreen. The water droplets come from water vapour in the air inside the car.\n\nName this change of state and describe what happens to the water particles.`, marks: 2, command: 'Describe', markScheme: `• Condensation / condensing (1)\n• The particles lose energy / slow down and move closer together (forming a liquid) (1)\nIgnore: particles get smaller / colder` },
      { q: `A student melts some ice by leaving it in a warm room.\n\nExplain, in terms of particles, what happens when the ice melts.`, marks: 3, command: 'Explain', markScheme: `• Energy is transferred to the particles (from the surroundings) (1)\n• The particles vibrate more / gain kinetic energy (1)\n• Some forces of attraction are overcome so the particles can move past each other / leave their fixed positions (1)\nDo not allow: particles expand / bonds in water molecules break` },
      { q: `In the alpha particle scattering experiment, alpha particles (which are positive) were fired at a very thin sheet of gold foil.\n\nMost alpha particles went straight through the foil. A very small number bounced back.\n\nExplain what these two observations show about the structure of the atom.`, marks: 3, command: 'Explain', markScheme: `• Most went straight through, so the atom is mostly empty space (1)\n• A very small number bounced back, so there is a small / tiny centre / nucleus (1)\n• The nucleus is positive / dense / contains most of the mass (so it repels the alpha particles) (1)` },
      { q: `Chlorine has two isotopes. Their symbols are ³⁵₁₇Cl and ³⁷₁₇Cl.\n\nCompare the numbers of protons, neutrons and electrons in atoms of these two isotopes.`, marks: 3, command: 'Compare', markScheme: `• Both have 17 protons (1)\n• Both have 17 electrons (1)\n• ³⁵Cl has 18 neutrons and ³⁷Cl has 20 neutrons (1)\nAllow: chlorine-37 has 2 more neutrons than chlorine-35 for the third mark` },
      { q: `Sulfur forms the sulfide ion, ³²₁₆S²⁻, in the compound zinc sulfide.\n\nCalculate the number of protons, neutrons and electrons in one sulfide ion.`, marks: 3, command: 'Calculate', markScheme: `• Protons = 16 (1)\n• Neutrons = 32 − 16 = 16 (1)\n• Electrons = 16 + 2 = 18 (1)` },
      { q: `A scientist analyses an ion, X²⁺. The ion has 18 electrons and 20 neutrons.\n\nUse the Periodic Table to identify element X and find the mass number of the ion. Show your working.`, marks: 3, command: 'Identify', markScheme: `• Protons = 18 + 2 = 20 (1)\n• X is calcium / Ca (1)\n• Mass number = 20 + 20 = 40 (1)\nAllow: ECF for mass number from an incorrect number of protons` },
      { q: `A teacher explains changes of state using a particle model in which particles are drawn as small, solid, inelastic spheres.\n\nDescribe three limitations of this model.`, marks: 3, command: 'Describe', markScheme: `Any three from:\n• It does not show the forces of attraction between the particles (1)\n• It does not show the size of the particles compared with the spaces between them / the spheres are not to scale (1)\n• Particles are not solid / they are made of atoms that are mostly empty space (1)\n• Particles are not all spheres / molecules have different shapes (1)\n• It does not show the movement / speed of the particles (1)\nMax 3` },
      { q: `Gold leaf is used to decorate cakes. A piece of gold leaf is 1.0 × 10⁻⁷ m thick. The diameter of a gold atom is 2.9 × 10⁻¹⁰ m (data written for this practice question).\n\nCalculate the number of gold atoms that are stacked through the thickness of the gold leaf.\n\nGive your answer to 2 significant figures.`, marks: 3, command: 'Calculate', markScheme: `• (1.0 × 10⁻⁷) ÷ (2.9 × 10⁻¹⁰) (1)\n• = 344.8… (1)\n• = 340 (to 2 s.f.) (1)\nAllow: 3.4 × 10² for the third mark` },
      { q: `A student compares Dalton's model of the atom with the modern model of the atom.\n\nDescribe three ways in which the modern model is different from Dalton's model.`, marks: 3, command: 'Describe', markScheme: `Any three from:\n• Atoms are not solid / are mostly empty space (1)\n• Atoms can be divided / contain smaller subatomic particles (1)\n• There is a (small, positive) nucleus containing protons and neutrons (1)\n• Electrons are in shells / energy levels around the nucleus (1)\n• Atoms of the same element are not all identical / isotopes have different masses (1)\nMax 3` },
      { q: `Iodine is a grey-black solid. When iodine is warmed gently it turns directly into a purple gas. When the gas touches a cold surface it turns back into a solid.\n\nExplain, in terms of particles, why this is a physical change and not a chemical change.`, marks: 3, command: 'Explain', markScheme: `• No new substance is formed / the gas is still iodine (1)\n• The iodine particles / molecules themselves do not change; only the arrangement / spacing / movement of the particles changes (1)\n• The change is easily reversed (by cooling) (1)\nDo not allow: atoms / bonds within iodine molecules break` },
      { q: `A student investigates the cooling of stearic acid. They melt some stearic acid in a boiling tube in a water bath, then remove the tube and record the temperature every 30 seconds.\n\nThe results are described below (data written for this practice question).\n• The temperature falls quickly from 90 °C to 69 °C.\n• The temperature stays at 69 °C for 5 minutes.\n• The temperature then falls slowly to 40 °C.\n\nDescribe and explain the shape of the cooling curve in terms of the states and the particles of stearic acid.`, marks: 4, command: 'Explain', markScheme: `• From 90 °C to 69 °C the stearic acid is a liquid and the particles lose (kinetic) energy / slow down (1)\n• At 69 °C the stearic acid is freezing / solidifying / 69 °C is the melting point (1)\n• The temperature stays constant because energy is released as forces of attraction form between particles / particles become fixed in a regular arrangement (1)\n• Below 69 °C the stearic acid is a solid and the particles vibrate less as it cools (1)` },
      { q: `The table shows information about four particles, A, B, C and D (data written for this practice question).\n\nParticle | Protons | Neutrons | Electrons\nA | 8 | 8 | 8\nB | 8 | 10 | 8\nC | 11 | 12 | 10\nD | 9 | 10 | 10\n\n(i) Which two particles are isotopes of the same element? Explain your answer.\n(ii) Particles C and D are ions. Give the charge on each ion.`, marks: 4, command: 'Explain', markScheme: `(i)\n• A and B (1)\n• Same number of protons / both have 8 protons, but different numbers of neutrons (1)\n(ii)\n• C: +1 / 1+ (1)\n• D: −1 / 1− (1)` },
      { q: `The table shows information about the particles in an atom.\n\nParticle | Relative charge | Relative mass | Where found in the atom\nproton | ? | 1 | ?\nneutron | 0 | ? | nucleus\nelectron | ? | ? | shells\n\nComplete the table.`, marks: 4, command: 'Complete', markScheme: `• Proton: relative charge +1 (1)\n• Proton: found in nucleus (1)\n• Neutron: relative mass 1 (1)\n• Electron: relative charge −1 and relative mass very small / 1/1840 / 0.0005 (1)\nAllow: negligible / almost 0 for the electron's mass\nDo not allow: 0 for the electron's mass` },
      { q: `Scientists' ideas about the structure of the atom have changed many times since the early 1800s. Models were suggested by Dalton, Thomson, Rutherford and Bohr.\n\nDescribe how the model of the atom has developed, and explain how new evidence led to each change.*`, marks: 6, command: 'Describe', markScheme: `Level 3 (5–6 marks)\nDescribes at least three models in the correct order AND explains the evidence that led to at least two changes.\nThere is a well-developed line of reasoning which is clear and logically structured. The information presented is relevant and substantiated.\n\nLevel 2 (3–4 marks)\nDescribes at least two models AND explains the evidence for at least one change.\nThere is a line of reasoning presented with some structure. The information presented is relevant and supported by some evidence.\n\nLevel 1 (1–2 marks)\nDescribes at least one model OR gives one piece of evidence.\nThere is an attempt at a logical structure with a line of reasoning. The information is in the most part relevant.\n\n0 marks\nNo response or no response worthy of credit.\n\nIndicative scientific points may include:\nModels\n• Dalton: atoms are tiny solid spheres that cannot be divided; atoms of each element are different\n• Thomson: plum pudding model, a sphere of positive charge with negative electrons embedded in it\n• Rutherford: nuclear model, a tiny, dense, positive nucleus with electrons around it; atom mostly empty space\n• Bohr: electrons orbit the nucleus in shells / energy levels at fixed distances\n• (Later) the nucleus contains protons and neutrons (Chadwick discovered the neutron)\nEvidence\n• Thomson discovered the electron, so atoms could be divided / contain smaller particles\n• Alpha particle scattering: most alpha particles passed straight through gold foil, so the atom is mostly empty space\n• A few were deflected / bounced back, so there is a small, dense, positive nucleus\n• Bohr's calculations matched experimental observations / explained why electrons do not spiral into the nucleus\n• Each model was changed because new evidence could not be explained by the old model` }
    ]
  },
  'C2': {
    name: 'Elements, Compounds and Mixtures',
    questions: [
      { q: `A student makes a sample of aspirin. Pure aspirin melts at 136 °C. The student's sample melts over the range 128–133 °C.\n\nWhat does this tell you about the student's sample?`, marks: 1, command: 'State', markScheme: `• The sample is impure / contains impurities (1)\nALLOW it is not pure aspirin / it is a mixture\nIGNORE it is not aspirin` },
      { q: `A student sets up paper chromatography to separate the dyes in a black felt-tip pen. She puts a spot of the ink on a pencil start line and stands the paper in a beaker of water.\n\nExplain why the level of the water must be below the start line.`, marks: 1, command: 'Explain', markScheme: `• Otherwise the dyes / ink would dissolve into the water in the beaker (instead of moving up the paper) (1)\nALLOW the spot would wash off into the solvent` },
      { q: `Element Q is in Group 3 and Period 3 of the Periodic Table.\n\nWrite down the electronic structure of an atom of element Q.`, marks: 1, command: 'Write', markScheme: `• 2.8.3 (1)\nALLOW 2,8,3` },
      { q: `Carbon exists in several different structures. Structure Z is a hollow, ball-shaped molecule made of 60 carbon atoms joined in rings of five and six atoms.\n\nName the type of carbon structure shown by structure Z.`, marks: 1, command: 'Name', markScheme: `• Fullerene (1)\nALLOW buckminsterfullerene / buckyball / C₆₀\nDO NOT ALLOW nanotube / graphene` },
      { q: `A sunscreen contains nanoparticles of titanium dioxide. Each particle has a diameter of 25 nm.\n\n1 nm = 1 × 10⁻⁹ m\n\nWrite 25 nm in metres. Give your answer in standard form.`, marks: 1, command: 'Write', markScheme: `• 2.5 × 10⁻⁸ m (1)\nDO NOT ALLOW 25 × 10⁻⁹ m (not standard form)` },
      { q: `A tin of gloss paint lists its ingredients: pigment 20%, binder 35%, solvent 40%, additives 5%. Each ingredient is added in a measured quantity so that the paint does its job well.\n\nComplete the sentence.\n\nA mixture that has been designed as a useful product, like this paint, is called a ……………………… .`, marks: 1, command: 'Complete', markScheme: `• formulation (1)\nIGNORE mixture / solution` },
      { q: `A carton of apple juice has the label "100% pure apple juice".\n\nA scientist says the apple juice is not pure.\n\nExplain why the scientist says this.`, marks: 2, command: 'Explain', markScheme: `• In chemistry, a pure substance contains only one element or one compound (1)\n• Apple juice is a mixture of different substances / contains water, sugars, acids etc. (1)\nIGNORE "nothing has been added" for the second mark` },
      { q: `A student uses paper chromatography to analyse a green food colouring. One of the spots moves 3.6 cm from the start line. The solvent front moves 8.0 cm from the start line.\n\nCalculate the Rf value of this spot.`, marks: 2, command: 'Calculate', markScheme: `• Rf = distance moved by spot ÷ distance moved by solvent = 3.6 ÷ 8.0 (1)\n• = 0.45 (1)\nCorrect answer with no working scores 2 marks\nDO NOT ALLOW an answer with units` },
      { q: `A forensic scientist wants to find out which pen was used to write a note. She uses chromatography to compare the ink from the note, ink X, with four dyes, A, B, C and D.\n\nThe chromatogram is described below.\n• Ink X gives two spots.\n• One spot of ink X is at the same height as the spot for dye B.\n• The other spot of ink X is at the same height as the spot for dye D.\n• Dyes A and C each give one spot at heights different from both spots of ink X.\n\nWhat does the chromatogram tell you about ink X?`, marks: 2, command: 'State', markScheme: `• Ink X is a mixture (of two dyes) / ink X is not pure (1)\n• Ink X contains dye B and dye D (but not A or C) (1)` },
      { q: `Calcium hydroxide, Ca(OH)₂, is added to fields by farmers to neutralise acidic soil.\n\nCalculate the relative formula mass, Mr, of calcium hydroxide.\n\nRelative atomic masses (Ar): Ca = 40.1  O = 16.0  H = 1.0`, marks: 2, command: 'Calculate', markScheme: `• 40.1 + 2 × (16.0 + 1.0) (1)\n• = 74.1 (1)\nALLOW 74 if Ca = 40 used\nCorrect answer with no working scores 2 marks` },
      { q: `Sodium reacts with chlorine to make sodium chloride.\n\n2Na + Cl₂ → 2NaCl\n\nShow that the total relative formula mass of the reactants is equal to the total relative formula mass of the products.\n\nRelative atomic masses (Ar): Na = 23.0  Cl = 35.5`, marks: 2, command: 'Show', markScheme: `• Reactants: (2 × 23.0) + (2 × 35.5) = 46.0 + 71.0 = 117.0 (1)\n• Products: 2 × (23.0 + 35.5) = 2 × 58.5 = 117.0, so they are equal (1)` },
      { q: `The table shows the molecular formulae of two compounds.\n\n| Compound | Molecular formula |\n| glucose | C₆H₁₂O₆ |\n| butane | C₄H₁₀ |\n\nWrite down the empirical formula of each compound.`, marks: 2, command: 'Write', markScheme: `• glucose: CH₂O (1)\n• butane: C₂H₅ (1)\nALLOW elements in any order, e.g. H₂CO` },
      { q: `A student has a mixture of sand and salt solution. He pours the mixture through filter paper in a funnel.\n\nName the substance left in the filter paper and the liquid that passes through the filter paper.`, marks: 2, command: 'Name', markScheme: `• Left in the filter paper (residue): sand (1)\n• Liquid passing through (filtrate): salt solution / sodium chloride solution (1)\nIGNORE salt / water alone for the filtrate` },
      { q: `A student wants to make crystals of copper sulfate from copper sulfate solution. She heats the solution in an evaporating basin until crystals start to form at the edge. She then leaves the solution to cool.\n\nHer friend says she should keep heating until all the water has gone.\n\nExplain why the student should not heat the solution until it is dry.`, marks: 2, command: 'Explain', markScheme: `• Heating to dryness would give a powder / small crystals instead of large crystals (1)\n• Copper sulfate crystals contain water (of crystallisation) which would be driven off / the crystals would decompose / spit (1)\nALLOW the solid may spit out of the basin / decompose for either mark` },
      { q: `A student uses simple distillation to get pure water from sea water. A thermometer is placed with its bulb level with the side arm of the flask.\n\nWhile the water is being collected, the thermometer reading stays at 100 °C.\n\nExplain why the thermometer reading stays at 100 °C.`, marks: 2, command: 'Explain', markScheme: `• 100 °C is the boiling point of water (1)\n• Only water vapour / pure water is reaching the thermometer; the salt does not evaporate / stays in the flask (1)` },
      { q: `Ethanol and water mix completely. Ethanol boils at 78 °C and water boils at 100 °C. A mixture of ethanol and water is separated using fractional distillation.\n\nWhich liquid is collected first? Explain your answer.`, marks: 2, command: 'Explain', markScheme: `• Ethanol (1)\n• It has the lower boiling point, so it evaporates first / reaches the top of the fractionating column and condenses first (1)\nThe second mark depends on ethanol being chosen` },
      { q: `The table shows some properties of two elements, J and K.\n(data written for this practice question)\n\n| Element | Appearance | Conducts electricity as a solid? | Effect of hammering |\n| J | yellow, dull | no | shatters |\n| K | grey, shiny | yes | flattens |\n\nWhich element, J or K, is a metal? Give two reasons for your answer.`, marks: 2, command: 'Give', markScheme: `• K is the metal AND one reason from: shiny / conducts electricity / malleable (flattens) (1)\n• A second correct reason (1)` },
      { q: `Magnesium reacts with oxygen to form magnesium oxide. Magnesium oxide contains magnesium ions, Mg²⁺.\n\nDescribe how a magnesium atom becomes a magnesium ion.`, marks: 2, command: 'Describe', markScheme: `• The magnesium atom loses electrons (1)\n• It loses two electrons (from its outer shell) (1)\nALLOW 2.8.2 → 2.8 for the second mark\nDO NOT ALLOW magnesium gains / shares electrons` },
      { q: `Ammonia, NH₃, is a simple covalent molecule. A nitrogen atom has 5 electrons in its outer shell. A hydrogen atom has 1 electron.\n\nDraw a dot and cross diagram to show the covalent bonding in a molecule of ammonia. Show the outer shell electrons only.`, marks: 2, command: 'Draw', diagram: true, markScheme: `• Three shared pairs of electrons, each pair made of one dot and one cross, between N and each H (1)\n• One lone (non-bonding) pair of electrons on the nitrogen atom, giving 8 outer electrons around N (1)\nIGNORE circles / inner shells` },
      { q: `The table shows the charges on some ions.\n\n| Ion | Formula |\n| aluminium | Al³⁺ |\n| calcium | Ca²⁺ |\n| chloride | Cl⁻ |\n| oxide | O²⁻ |\n\nWrite the formulae of aluminium oxide and calcium chloride.`, marks: 2, command: 'Write', markScheme: `• aluminium oxide: Al₂O₃ (1)\n• calcium chloride: CaCl₂ (1)` },
      { q: `Copper is used to make electrical wires because it is a good conductor of electricity.\n\nExplain why metals like copper conduct electricity. Use ideas about metallic bonding.`, marks: 2, command: 'Explain', markScheme: `• Metals contain delocalised electrons / a sea of free electrons (1)\n• The electrons can move (through the structure) and carry charge (1)\nDO NOT ALLOW ions moving` },
      { q: `Chlorine, Cl₂, is a gas at room temperature. It boils at –34 °C.\n\nExplain why chlorine has a low boiling point.`, marks: 2, command: 'Explain', markScheme: `• Chlorine is made of small / simple molecules (1)\n• The intermolecular forces (between molecules) are weak, so little energy is needed to overcome them (1)\nDO NOT ALLOW covalent bonds break / weak covalent bonds for the second mark` },
      { q: `A student tests the electrical conductivity of sodium chloride. Solid sodium chloride does not conduct electricity. When the sodium chloride is melted, it does conduct electricity.\n\nExplain these results.`, marks: 2, command: 'Explain', markScheme: `• In the solid, the ions are held in fixed positions / cannot move (1)\n• When molten, the ions are free to move and carry charge (1)\nDO NOT ALLOW electrons moving` },
      { q: `Diamond and graphite are both made only of carbon atoms. Graphite is used to make electrodes because it conducts electricity. Diamond does not conduct electricity.\n\nExplain why graphite conducts electricity but diamond does not.`, marks: 2, command: 'Explain', markScheme: `• In graphite each carbon atom forms three covalent bonds, so one electron per atom is delocalised / free to move (1)\n• In diamond each carbon atom forms four covalent bonds, so there are no free / delocalised electrons (1)` },
      { q: `Graphene is a single layer of carbon atoms arranged in hexagons. Scientists are developing graphene for use in very thin, flexible touch screens.\n\nGive two properties of graphene that make it suitable for touch screens.`, marks: 2, command: 'Give', markScheme: `Any two from:\n• conducts electricity (1)\n• very strong (1)\n• flexible / very thin / lightweight (1)\n• transparent / lets light through (1)` },
      { q: `Poly(ethene) is a polymer used to make plastic bags. It softens at about 120 °C. Diamond does not melt until over 3500 °C.\n\nExplain why poly(ethene) softens at a much lower temperature than diamond.`, marks: 2, command: 'Explain', markScheme: `• Poly(ethene) has (weak) intermolecular forces between its long chains / molecules which are easily overcome (1)\n• Diamond is a giant covalent structure, so many strong covalent bonds must be broken (1)\nDO NOT ALLOW covalent bonds break in poly(ethene)` },
      { q: `A teacher shows a class a ball-and-stick model of a methane molecule, CH₄, and a dot and cross diagram of methane drawn on the board.\n\nGive one limitation of the ball-and-stick model and one limitation of the dot and cross diagram.`, marks: 2, command: 'Give', markScheme: `• Ball-and-stick: one from: bonds are not really sticks / atoms are not solid balls / does not show the electrons / atoms are not to scale / shows too much space between atoms (1)\n• Dot and cross: one from: does not show the 3D shape / does not show the relative sizes of atoms / electrons are all the same, not dots and crosses (1)` },
      { q: `A chemist analyses a food colouring, F, using paper chromatography. She compares it with three permitted colourings, P, Q and R.\n\nThe Rf values of the spots are shown in the table.\n(data written for this practice question)\n\n| Substance | Rf values of spots |\n| F | 0.18, 0.52, 0.74 |\n| P | 0.52 |\n| Q | 0.30 |\n| R | 0.74 |\n\nWhat conclusions can the chemist make about food colouring F?`, marks: 3, command: 'Explain', markScheme: `• F is a mixture / contains three substances (1)\n• F contains P and R (because the Rf values match) but does not contain Q (1)\n• F contains one other substance (Rf 0.18) that is not P, Q or R / is not one of the permitted colourings tested (1)` },
      { q: `A student heats iron in oxygen. She finds that 11.2 g of iron combines with 4.8 g of oxygen to make an oxide of iron.\n\nCalculate the empirical formula of the oxide of iron.\n\nRelative atomic masses (Ar): Fe = 56.0  O = 16.0`, marks: 3, command: 'Calculate', markScheme: `• Moles of Fe = 11.2 ÷ 56.0 = 0.20 AND moles of O = 4.8 ÷ 16.0 = 0.30 (1)\n• Ratio Fe : O = 0.20 : 0.30 = 2 : 3 (1)\n• Fe₂O₃ (1)\nCorrect formula with no working scores 3 marks` },
      { q: `A student investigates the dyes in a red sweet using paper chromatography. One dye moves 33 mm from the start line. The solvent front moves 5.5 cm from the start line.\n\nThe table shows the Rf values of three dyes in the same solvent.\n\n| Dye | Rf value |\n| E | 0.25 |\n| F | 0.60 |\n| G | 0.80 |\n\nCalculate the Rf value of the dye in the sweet and identify the dye.`, marks: 3, command: 'Calculate', markScheme: `• Converts to the same units, e.g. 5.5 cm = 55 mm OR 33 mm = 3.3 cm (1)\n• Rf = 33 ÷ 55 = 0.60 (1)\n• Dye F (1)\nALLOW ECF for identification from an incorrect Rf value\nRf of 6 (no unit conversion) scores 0 for the first two marks` },
      { q: `A technician needs to separate three different mixtures.\n\n| Mixture | What the technician wants to obtain |\n| chalk powder in water | the chalk |\n| copper sulfate solution | solid copper sulfate |\n| ink dissolved in water | pure water |\n\nSuggest the best separation technique for each mixture.`, marks: 3, command: 'Suggest', markScheme: `• chalk in water: filtration (1)\n• copper sulfate solution: crystallisation (1)\nALLOW evaporation\n• ink in water: (simple) distillation (1)\nDO NOT ALLOW fractional distillation / chromatography for the third mark` },
      { q: `Calcium fluoride, CaF₂, is an ionic compound found in the mineral fluorite. The electronic structure of calcium is 2.8.8.2 and of fluorine is 2.7.\n\nDescribe how calcium and fluorine atoms form calcium fluoride. Use ideas about electrons.`, marks: 3, command: 'Describe', markScheme: `• Calcium atom loses / transfers two electrons (1)\n• Each fluorine atom gains one electron, so two fluorine atoms are needed (1)\n• Forming Ca²⁺ and F⁻ ions, which are attracted to each other by (strong) electrostatic forces (1)\nDO NOT ALLOW sharing of electrons` },
      { q: `The table shows information about three substances, W, X and Y.\n(data written for this practice question)\n\n| Substance | Melting point (°C) | Conducts electricity when solid? | Conducts electricity when liquid? |\n| W | 1083 | yes | yes |\n| X | 1610 | no | no |\n| Y | 770 | no | yes |\n\nIdentify the type of structure in each substance.\n\nChoose from: giant covalent, giant ionic, giant metallic, simple molecular.`, marks: 3, command: 'Identify', markScheme: `• W: giant metallic (1)\n• X: giant covalent (1)\n• Y: giant ionic (1)` },
      { q: `An atom of element T has 17 electrons.\n\nExplain which group and which period of the Periodic Table element T is in. Use the electronic structure of T in your answer.`, marks: 3, command: 'Explain', markScheme: `• Electronic structure 2.8.7 (1)\n• Group 7, because it has 7 electrons in its outer shell (1)\n• Period 3, because it has three (occupied) shells (1)\nALLOW ECF from an incorrect electronic structure for marks 2 and 3` },
      { q: `Cerium oxide nanoparticles are added to diesel fuel to help it burn more completely. A scientist models a nanoparticle as a cube with sides of 20 nm.\n\nCalculate the surface area to volume ratio of the nanoparticle. Then compare it with a cube-shaped particle of side 2000 nm, which has a surface area to volume ratio of 0.003 nm⁻¹.`, marks: 3, command: 'Calculate', markScheme: `• Surface area = 6 × 20 × 20 = 2400 nm² AND volume = 20 × 20 × 20 = 8000 nm³ (1)\n• Ratio = 2400 ÷ 8000 = 0.3 (nm⁻¹) (1)\n• The nanoparticle's ratio is 100 times larger (1)\nALLOW ECF for the comparison` },
      { q: `In 1869 Dmitri Mendeleev published a table of the elements. He left gaps in his table. Later, the element germanium was discovered. Its properties were very close to those Mendeleev had predicted for one of the gaps.\n\nExplain how Mendeleev arranged the elements, why he left gaps, and why the discovery of germanium was important.`, marks: 3, command: 'Explain', markScheme: `• Arranged in order of atomic mass AND put elements with similar properties in the same group / column (1)\n• Gaps were left for elements that had not yet been discovered (so that the pattern of properties was kept) (1)\n• Germanium fitted his predictions, so it provided evidence that his table / ideas were correct (1)` },
      { q: `A student has a mixture of sand and potassium nitrate. Potassium nitrate is soluble in water. Sand is insoluble in water.\n\nDescribe how the student can obtain pure, dry crystals of potassium nitrate from the mixture.`, marks: 4, command: 'Describe', markScheme: `• Add (warm) water and stir to dissolve the potassium nitrate (1)\n• Filter to remove the sand (1)\n• Heat the filtrate to evaporate some of the water until crystals start to form, then leave to cool (1)\n• Filter off the crystals and dry them, e.g. between filter paper / in a warm oven / desiccator (1)` },
      { q: `The table shows the melting points of three substances.\n\n| Substance | Melting point (°C) |\n| chlorine, Cl₂ | –101 |\n| sodium chloride, NaCl | 801 |\n| magnesium oxide, MgO | 2852 |\n\nExplain the differences in the melting points of these three substances. Use ideas about structure and bonding.`, marks: 4, command: 'Explain', markScheme: `• Chlorine is simple molecular with weak intermolecular forces, which need little energy to overcome (1)\n• Sodium chloride and magnesium oxide are giant ionic lattices (1)\n• with strong electrostatic attraction between oppositely charged ions, needing a lot of energy to overcome (1)\n• Magnesium oxide has ions with greater charges (Mg²⁺ and O²⁻ compared with Na⁺ and Cl⁻), so the attraction is stronger (1)` },
      { q: `Some sports socks contain silver nanoparticles. The silver nanoparticles kill bacteria that cause bad smells. When the socks are washed, some of the nanoparticles are released into waste water.\n\nExplain why silver nanoparticles are more effective than larger pieces of silver, and suggest one risk of using them in socks.`, marks: 4, command: 'Explain', markScheme: `• Nanoparticles are 1–100 nm in size / only a few hundred atoms (1)\n• They have a very large surface area to volume ratio (1)\n• So more silver atoms are exposed / available to contact and kill bacteria, so a smaller mass is needed (1)\n• Risk: one from: nanoparticles in waste water may harm useful bacteria / aquatic life / their long-term effects on health and the environment are not yet known / they could be absorbed through the skin (1)` },
      { q: `A sweet manufacturer suspects that a batch of orange sweets has been made with an orange food colouring that contains a banned dye. The manufacturer has samples of the permitted orange colouring and of the banned dye.\n\nA chemist uses paper chromatography to find out whether the sweets contain the banned dye.\n\nDescribe how the chemist should carry out the chromatography, and explain how the results can be used to decide whether the sweets contain the banned dye. Include ideas about Rf values in your answer.`, marks: 6, command: 'Describe', markScheme: `Level 3 (5–6 marks)\nGives a detailed method that would produce a valid chromatogram AND explains clearly how to compare the results, including calculating and comparing Rf values.\nThere is a well-developed line of reasoning which is clear and logically structured. The information presented is relevant and substantiated.\n\nLevel 2 (3–4 marks)\nGives a method with some detail AND explains how the chromatogram is compared OR gives a detailed method with a limited explanation of the results.\nThere is a line of reasoning presented with some structure. The information presented is relevant and supported by some evidence.\n\nLevel 1 (1–2 marks)\nGives a simple description of the method OR a simple statement about matching spots.\nThe information is basic and communicated in an unstructured way.\n\n0 marks\nNo response or no response worthy of credit.\n\nIndicative scientific points may include:\nMethod\n• dissolve the colouring from a sweet in a small amount of water / solvent\n• draw a start line in pencil near the bottom of the chromatography paper (pencil does not dissolve)\n• put small spots of the sweet colouring, the permitted colouring and the banned dye on the line, spaced apart\n• stand the paper in a beaker of solvent, with the solvent below the start line\n• put a lid on the beaker so the solvent does not evaporate\n• remove the paper when the solvent is near the top and mark the solvent front; let it dry\nAnalysis\n• compare the spots from the sweet with the spots from the banned dye and permitted colouring\n• if a spot from the sweet is at the same height as the banned dye, the sweet may contain the banned dye\n• Rf = distance moved by spot ÷ distance moved by solvent\n• matching Rf values (in the same solvent) identify the same substance\n• repeat with a different solvent to confirm, because two substances may have the same Rf in one solvent` }
    ]
  },
  'C3': {
    name: 'Chemical Reactions',
    questions: [
      { q: `Calcium nitrate is used in some garden fertilisers.\nThe table shows the formulae of some ions.\nCalcium ion: Ca²⁺   Nitrate ion: NO₃⁻   Potassium ion: K⁺   Sulfate ion: SO₄²⁻\n\nWrite the formula of calcium nitrate.`, marks: 1, command: 'Write', markScheme: `• Ca(NO₃)₂ (1)\nDO NOT ALLOW CaNO₃₂ or CaNO₃ (brackets needed)\nIGNORE charges shown on the ions within the formula if formula correct` },
      { q: `A student strikes a match. The match does not light until it is rubbed against the side of the box. Once it is lit, it keeps burning.\n\nWhat is meant by the term activation energy?`, marks: 1, command: 'State', markScheme: `• The minimum energy needed (by particles) to start a reaction / for a reaction to happen (1)\nALLOW minimum energy for a successful collision\nDO NOT ALLOW 'energy needed to start a reaction' without the idea of minimum` },
      { q: `A student tests some household substances with universal indicator solution.\nThe indicator turns purple when it is added to a solution of drain cleaner.\n\nEstimate the pH of the drain cleaner solution.`, marks: 1, command: 'Estimate', markScheme: `• Any value from 12 to 14 (1)\nALLOW a range wholly within 12–14` },
      { q: `A teacher electrolyses lead bromide, PbBr₂, using graphite electrodes.\nThe teacher heats the lead bromide until it melts before switching on the power supply.\n\nExplain why the lead bromide must be molten.`, marks: 1, command: 'Explain', markScheme: `• (So that) the ions are free to move (to the electrodes) (1)\nALLOW ions can move / ions are not fixed in a lattice\nDO NOT ALLOW electrons free to move\nIGNORE 'so it conducts' on its own` },
      { q: `A student weighs out 0.50 mol of copper powder.\nThe Avogadro constant is 6.02 × 10²³.\n\nCalculate the number of copper atoms in 0.50 mol of copper.`, marks: 1, command: 'Calculate', markScheme: `• 3.01 × 10²³ (atoms) (1)\nALLOW 301 000 000 000 000 000 000 000 / 3.0 × 10²³` },
      { q: `A student adds dilute nitric acid to potassium hydroxide solution. A neutralisation reaction takes place.\n\nWrite the ionic equation for the reaction between an acid and an alkali. Include state symbols.`, marks: 1, command: 'Write', markScheme: `• H⁺(aq) + OH⁻(aq) → H₂O(l) (1)\nBoth equation and state symbols needed for the mark\nALLOW = or ⇌ for →` },
      { q: `Propane, C₃H₈, is used as a fuel in camping stoves. When propane burns completely, carbon dioxide and water are made.\nThis is the unbalanced equation for the reaction.\n\nC₃H₈ + ……O₂ → ……CO₂ + ……H₂O\n\nBalance the equation.`, marks: 2, command: 'Balance', markScheme: `• C₃H₈ + 5O₂ → 3CO₂ + 4H₂O (2)\nAward 1 mark for 3CO₂ and 4H₂O correct but O₂ incorrect\nALLOW correct multiples, e.g. 2C₃H₈ + 10O₂ → 6CO₂ + 8H₂O` },
      { q: `A student puts a conical flask containing dilute hydrochloric acid and some sodium carbonate powder on a balance. The flask has no lid.\nThe reading on the balance goes down as the reaction happens.\nNa₂CO₃(s) + 2HCl(aq) → 2NaCl(aq) + H₂O(l) + CO₂(g)\n\nExplain why the reading on the balance goes down.`, marks: 2, command: 'Explain', markScheme: `• Carbon dioxide (gas) is made (1)\n• The gas escapes from the (open) flask (so its mass is not measured) (1)\nALLOW 'a gas is given off and leaves the flask' for 2 marks\nDO NOT ALLOW mass is destroyed / atoms are lost` },
      { q: `Calcium hydroxide, Ca(OH)₂, is added to soil to reduce its acidity.\nRelative atomic masses (Aᵣ): Ca = 40.1  O = 16.0  H = 1.0\n\nCalculate the relative formula mass (Mᵣ) of calcium hydroxide.`, marks: 2, command: 'Calculate', markScheme: `• 40.1 + 2 × (16.0 + 1.0) (1)\n• = 74.1 (2)\nCorrect answer with no working scores 2 marks\nALLOW 1 mark for 57.1 (brackets not expanded: 40.1 + 16.0 + 1.0)` },
      { q: `A scientist burns a candle under a cooled funnel and collects the water produced.\nThe scientist collects 9.0 g of water, H₂O.\nRelative atomic masses (Aᵣ): H = 1.0  O = 16.0\n\nCalculate the number of moles of water collected.`, marks: 2, command: 'Calculate', markScheme: `• Mᵣ of H₂O = 18.0 (1)\n• Moles = 9.0 ÷ 18.0 = 0.50 (mol) (1)\nCorrect answer with no working scores 2 marks\nALLOW ECF from an incorrect Mᵣ for the second mark` },
      { q: `A fire extinguisher releases carbon dioxide gas, CO₂.\nA small test sample of the gas has a mass of 4.4 g.\nRelative atomic masses (Aᵣ): C = 12.0  O = 16.0\nThe Avogadro constant is 6.02 × 10²³.\n\nCalculate the number of carbon dioxide molecules in 4.4 g of carbon dioxide.\nGive your answer in standard form.`, marks: 2, command: 'Calculate', markScheme: `• Moles of CO₂ = 4.4 ÷ 44.0 = 0.10 (mol) (1)\n• Number of molecules = 0.10 × 6.02 × 10²³ = 6.02 × 10²² (1)\nCorrect answer with no working scores 2 marks\nALLOW ECF from incorrect number of moles\nALLOW 6.0 × 10²²\nAnswer not in standard form (60 200 000 000 000 000 000 000) scores 1 mark` },
      { q: `A student adds a 5 cm length of magnesium ribbon to 25 cm³ of dilute hydrochloric acid in a boiling tube.\nAfter the fizzing stops, some magnesium ribbon is still left in the tube.\n\nWhich reactant is the limiting reactant? Explain your answer.`, marks: 2, command: 'Explain', markScheme: `• (Hydrochloric) acid (1)\n• Because it has all been used up / it has run out, so the reaction stops (while magnesium is left over / in excess) (1)\nThe second mark is dependent on the first` },
      { q: `Cold packs are used to treat sports injuries. When the pack is squeezed, a solid dissolves in water inside the pack.\nA student measures the temperature of the contents of a cold pack. The temperature falls from 22.0 °C to 6.5 °C.\n\nIs dissolving the solid exothermic or endothermic? Explain your answer.`, marks: 2, command: 'Explain', markScheme: `• Endothermic (1)\n• Energy is taken in from the surroundings (so the temperature decreases) (1)\nALLOW heat for energy\nDO NOT ALLOW 'cold is given out'\nThe second mark is dependent on the first` },
      { q: `Methane, CH₄, is the main gas in natural gas. It burns in oxygen in an exothermic reaction.\nCH₄ + 2O₂ → CO₂ + 2H₂O\n\nExplain, in terms of breaking and making bonds, why this reaction is exothermic.`, marks: 2, command: 'Explain', markScheme: `• Energy is taken in to break bonds and given out when bonds are made (1)\n• More energy is given out making the bonds (in CO₂ and H₂O) than is taken in breaking the bonds (in CH₄ and O₂) (1)\nALLOW energy released forming new bonds is greater than energy needed to break bonds for 2 marks\nDO NOT ALLOW breaking bonds releases energy` },
      { q: `The thermite reaction is used to weld railway tracks. Aluminium reacts with iron(III) oxide to make molten iron.\n2Al + Fe₂O₃ → Al₂O₃ + 2Fe\n\nIdentify which substance is oxidised and which substance is reduced in this reaction. Explain your answers in terms of oxygen.`, marks: 2, command: 'Identify', markScheme: `• Aluminium is oxidised because it gains oxygen (1)\n• Iron(III) oxide is reduced because it loses oxygen (1)\nALLOW iron oxide / Fe₂O₃ / iron is reduced\nIf no explanation is given for either, maximum 1 mark for both identifications correct` },
      { q: `A student puts a piece of zinc into copper sulfate solution. The blue colour of the solution fades and a brown solid forms on the zinc.\nZn(s) + Cu²⁺(aq) → Zn²⁺(aq) + Cu(s)\n\nWrite the half equation for the change to zinc and explain why this change is an oxidation.`, marks: 2, command: 'Write', markScheme: `• Zn → Zn²⁺ + 2e⁻ (1)\n• (Oxidation because) zinc (atoms) lose electrons (1)\nALLOW Zn − 2e⁻ → Zn²⁺\nIGNORE state symbols\nALLOW OIL RIG quoted only if applied to zinc losing electrons` },
      { q: `A label on a bottle of vinegar says 'contains dilute ethanoic acid. Ethanoic acid is a weak acid.'\nA student says: "Dilute and weak mean the same thing."\n\nExplain why the student is wrong.`, marks: 2, command: 'Explain', markScheme: `• Dilute means there is a small amount of acid dissolved in a large volume of water / low concentration (1)\n• Weak means the acid is only partially ionised (in water) (1)\nALLOW partially dissociates / does not fully ionise / only some molecules release H⁺ ions\nDO NOT ALLOW weak means low pH / weak means few molecules` },
      { q: `A sample of hydrochloric acid has a pH of 2. A student dilutes the acid with water. The pH of the diluted acid is 5.\n\nDescribe how the concentration of hydrogen ions has changed.`, marks: 2, command: 'Describe', markScheme: `• Concentration (of H⁺ ions) decreases (1)\n• By a factor of 1000 / 10³ (1)\nALLOW 'it is 1000 times smaller' for 2 marks\nAward 1 mark for 'changes by a factor of 1000' with no direction or for 'decreases by a factor of 3 / 30'` },
      { q: `Zinc sulfate is used in some medicines. A student makes zinc sulfate by adding zinc to dilute sulfuric acid.\n\nComplete the word equation for this reaction.\nzinc + sulfuric acid → ……………… + ………………`, marks: 2, command: 'Complete', markScheme: `• zinc sulfate (1)\n• hydrogen (1)\nEither order\nDO NOT ALLOW water for hydrogen\nDO NOT ALLOW formulae with errors` },
      { q: `Limestone is mainly calcium carbonate, CaCO₃. Some buildings made of limestone are damaged by acid rain.\nA student models this by adding dilute hydrochloric acid to calcium carbonate.\n\nWrite a balanced symbol equation for the reaction between calcium carbonate and hydrochloric acid.`, marks: 2, command: 'Write', markScheme: `• Correct formulae: CaCO₃ + HCl → CaCl₂ + H₂O + CO₂ (1)\n• Balanced: CaCO₃ + 2HCl → CaCl₂ + H₂O + CO₂ (1)\nIGNORE state symbols\nALLOW H₂CO₃ in place of H₂O + CO₂ for first mark only` },
      { q: `A student makes copper sulfate crystals from copper oxide and dilute sulfuric acid.\nThe student warms the acid and adds copper oxide powder, one spatula at a time, while stirring.\n\nHow does the student know when the copper oxide is in excess? Give one reason why it is added in excess.`, marks: 2, command: 'Give', markScheme: `• Black solid / copper oxide no longer dissolves / stays at the bottom of the beaker (1)\n• So that all of the acid is used up / reacted / neutralised (1)\nALLOW so that the solution contains only copper sulfate / no acid is left in the salt` },
      { q: `A student does a titration to find the volume of dilute hydrochloric acid needed to neutralise 25.0 cm³ of sodium hydroxide solution. The table shows the student's results (data written for this practice question).\nRough titre: 25.10 cm³   Titre 1: 24.20 cm³   Titre 2: 24.60 cm³   Titre 3: 24.30 cm³\nConcordant titres are within 0.10 cm³ of each other.\n\nCalculate the mean titre. Use only the concordant titres.`, marks: 2, command: 'Calculate', markScheme: `• Selects titre 1 and titre 3 only / (24.20 + 24.30) ÷ 2 (1)\n• 24.25 (cm³) (1)\nALLOW 24.3 (cm³)\nAward 1 mark for 24.37 (mean of titres 1, 2 and 3) or 24.55 (mean of all four)` },
      { q: `Zinc is extracted from zinc chloride, ZnCl₂, in a laboratory demonstration. A teacher electrolyses molten zinc chloride using graphite electrodes.\n\nPredict the product made at each electrode.`, marks: 2, command: 'Predict', markScheme: `• Cathode / negative electrode: zinc (1)\n• Anode / positive electrode: chlorine (1)\nALLOW Zn and Cl₂\nDO NOT ALLOW chloride / Cl` },
      { q: `Lead is made at the cathode and bromine at the anode when molten lead bromide, PbBr₂, is electrolysed.\n\nWrite the half equations for the reactions at the cathode and at the anode.`, marks: 2, command: 'Write', markScheme: `• Cathode: Pb²⁺ + 2e⁻ → Pb (1)\n• Anode: 2Br⁻ → Br₂ + 2e⁻ (1)\nALLOW 2Br⁻ − 2e⁻ → Br₂\nIGNORE state symbols\nALLOW = for →` },
      { q: `A student electrolyses potassium nitrate solution, KNO₃(aq), using inert electrodes. Bubbles of gas form at both electrodes.\n\nName the gas made at the cathode and the gas made at the anode.`, marks: 2, command: 'Name', markScheme: `• Cathode: hydrogen (1)\n• Anode: oxygen (1)\nDO NOT ALLOW potassium / nitrogen\nALLOW H₂ and O₂` },
      { q: `A water company tests a sample of tap water for chloride ions. A few drops of dilute nitric acid and then silver nitrate solution are added. A white precipitate of silver chloride, AgCl, forms.\n\nWrite the ionic equation for the formation of the precipitate. Include state symbols.`, marks: 2, command: 'Write', markScheme: `• Ag⁺ + Cl⁻ → AgCl (1)\n• State symbols: Ag⁺(aq) + Cl⁻(aq) → AgCl(s) (1)\nState symbol mark is dependent on correct equation\nDO NOT ALLOW full equation with NO₃⁻ ions shown on both sides for the first mark` },
      { q: `This question is about compounds used in water treatment.\nThe table shows the formulae of some ions.\nAluminium ion: Al³⁺   Oxide ion: O²⁻   Ammonium ion: NH₄⁺   Sulfate ion: SO₄²⁻\n\nWrite the formula of aluminium oxide and the formula of ammonium sulfate.`, marks: 2, command: 'Write', markScheme: `• Aluminium oxide: Al₂O₃ (1)\n• Ammonium sulfate: (NH₄)₂SO₄ (1)\nDO NOT ALLOW NH₄₂SO₄ (brackets needed)\nIGNORE charges on ions if overall formula correct` },
      { q: `A student heats copper carbonate, CuCO₃, in a crucible. Copper carbonate decomposes:\nCuCO₃(s) → CuO(s) + CO₂(g)\nThe student's results are shown below (data written for this practice question).\nMass of empty crucible = 20.00 g\nMass of crucible + copper carbonate = 22.47 g\nMass of crucible + contents after heating to constant mass = 21.59 g\nRelative atomic masses (Aᵣ): C = 12.0  O = 16.0  Cu = 63.5\n\nShow that the student's results agree with the equation for the reaction.`, marks: 3, command: 'Show', markScheme: `• Moles of CuCO₃ = 2.47 ÷ 123.5 = 0.0200 (mol) (1)\n• Mass of CO₂ lost = 22.47 − 21.59 = 0.88 g, so moles of CO₂ = 0.88 ÷ 44.0 = 0.0200 (mol) (1)\n• Moles of CuCO₃ : moles of CO₂ = 1 : 1, the same as the equation (1)\nALLOW alternative: expected mass of CuO = 0.0200 × 79.5 = 1.59 g; residue = 21.59 − 20.00 = 1.59 g, which matches (3)` },
      { q: `Calcium oxide, CaO, is made by heating calcium carbonate, CaCO₃, in a lime kiln.\nCaCO₃ → CaO + CO₂\nA student heats 25.0 g of calcium carbonate in the laboratory.\nRelative atomic masses (Aᵣ): C = 12.0  O = 16.0  Ca = 40.1\n\nCalculate the maximum mass of calcium oxide that can be made.\nGive your answer to 3 significant figures.`, marks: 3, command: 'Calculate', markScheme: `• Mᵣ CaCO₃ = 100.1 and Mᵣ CaO = 56.1 (1)\n• Moles of CaCO₃ = 25.0 ÷ 100.1 = 0.250 (mol) (= moles of CaO) (1)\n• Mass of CaO = 0.24975 × 56.1 = 14.0 (g) (1)\nCorrect answer with no working scores 3 marks\nALLOW ECF throughout\nALLOW 14.01 (g) for 2 marks (not 3 s.f.)` },
      { q: `When sodium hydrogencarbonate reacts with citric acid, the temperature of the mixture decreases. The reaction is endothermic.\n\nDraw a reaction profile for this reaction. Label the reactants, the products, the activation energy and the overall energy change.`, marks: 3, command: 'Draw', diagram: true, markScheme: `• Products drawn at a higher energy level than reactants, with reactants and products labelled (1)\n• Curve rising from the reactants to a peak above the products and falling to the products, with activation energy shown as an arrow from reactants to the top of the peak (1)\n• Overall energy change shown as an arrow from the reactants level to the products level (upwards) (1)\nAxes need not be labelled for marks, but y-axis is energy and x-axis is progress of reaction\nDO NOT ALLOW activation energy arrow from products to peak` },
      { q: `Sodium chloride solution, NaCl(aq), is electrolysed using inert electrodes. Hydrogen is made at the cathode and chlorine is made at the anode.\n\nExplain why hydrogen, not sodium, is made at the cathode, and why chlorine, not oxygen, is made at the anode.`, marks: 3, command: 'Explain', markScheme: `• The solution contains Na⁺, H⁺, Cl⁻ and OH⁻ ions / H⁺ and OH⁻ ions come from water (1)\n• Hydrogen is made because hydrogen is less reactive than sodium (so H⁺ ions are discharged instead of Na⁺) (1)\n• Chlorine is made because chloride / halide ions are present (in high concentration) and are discharged in preference to hydroxide ions (1)\nALLOW sodium is more reactive than hydrogen\nDO NOT ALLOW chlorine ions` },
      { q: `Magnesium burns in chlorine gas to make magnesium chloride.\nMg + Cl₂ → MgCl₂\nMagnesium chloride contains Mg²⁺ and Cl⁻ ions.\n\nExplain, in terms of electrons, why this is a redox reaction.`, marks: 3, command: 'Explain', markScheme: `• Magnesium (atoms) lose (two) electrons / Mg → Mg²⁺ + 2e⁻ (1)\n• Chlorine (molecules / atoms) gain electrons / Cl₂ + 2e⁻ → 2Cl⁻ (1)\n• Loss of electrons is oxidation and gain of electrons is reduction, and both happen at the same time (1)\nALLOW magnesium is oxidised and chlorine is reduced for the third mark if linked to electron transfer\nDO NOT ALLOW chloride gains electrons` },
      { q: `A student adds sodium hydroxide solution, 5 cm³ at a time, to 20 cm³ of dilute hydrochloric acid. She measures the pH with a pH meter after each addition. The results are shown below (data written for this practice question).\nVolume of sodium hydroxide added (cm³): 0, 5, 10, 15, 20, 25, 30\npH: 1.0, 1.2, 1.5, 2.1, 7.0, 12.0, 12.4\n\nDescribe how the pH changes as the sodium hydroxide is added. Use the data in your answer.`, marks: 3, command: 'Describe', markScheme: `• pH starts low / acidic (pH 1.0) and increases slowly at first, from 1.0 to 2.1 between 0 and 15 cm³ (1)\n• pH increases sharply / rapidly between 15 cm³ and 25 cm³ (from 2.1 to 12.0) (1)\n• Neutral / pH 7 at 20 cm³, then levels off at a high / alkaline pH (12.4) when alkali is in excess (1)\nAt least one correct data quote needed for full marks` },
      { q: `A student electrolyses copper sulfate solution using two copper electrodes. Copper electrodes are non-inert electrodes.\nThe student weighs each electrode before and after the experiment.\n\nDescribe and explain what happens to the mass of the anode and the mass of the cathode.`, marks: 3, command: 'Describe', markScheme: `• Anode loses mass and cathode gains mass (1)\n• At the anode, copper atoms lose electrons and go into the solution as Cu²⁺ ions / Cu → Cu²⁺ + 2e⁻ (1)\n• At the cathode, Cu²⁺ ions gain electrons and are deposited as copper (metal) / Cu²⁺ + 2e⁻ → Cu (1)\nALLOW the mass lost by the anode is equal to the mass gained by the cathode` },
      { q: `A student wants to find out if the reaction between hydrochloric acid and sodium hydroxide solution is exothermic.\nThe student has a polystyrene cup, a 250 cm³ beaker, a thermometer and two measuring cylinders.\n\nDescribe how the student can use this apparatus to measure the temperature change.`, marks: 3, command: 'Describe', markScheme: `• Measure a known volume of acid (e.g. 25 cm³) into the polystyrene cup (standing in the beaker) and record the starting temperature (1)\n• Add a known volume of sodium hydroxide solution (measured with the other measuring cylinder) and stir (1)\n• Record the highest temperature reached and subtract the starting temperature (1)\nALLOW use a lid on the cup / repeat and calculate a mean for the third mark if the highest temperature is referred to\nIGNORE references to safety` },
      { q: `A student adds identical pieces of magnesium ribbon to two acids at the same temperature (data written for this practice question).\nAcid A: hydrochloric acid, concentration 0.10 mol/dm³, pH 1.0, fizzes quickly\nAcid B: ethanoic acid, concentration 0.10 mol/dm³, pH 2.9, fizzes slowly\n\nExplain the differences in pH and in the speed of fizzing.`, marks: 3, command: 'Explain', markScheme: `• Hydrochloric acid is a strong acid and is completely / fully ionised (in water) (1)\n• Ethanoic acid is a weak acid and is only partially ionised (1)\n• So hydrochloric acid has a higher concentration of H⁺ ions, so it has a lower pH and reacts faster with magnesium (1)\nALLOW dissociated for ionised\nDO NOT ALLOW ethanoic acid is more dilute` },
      { q: `Hydrogen is being tested as a fuel for buses. Hydrogen burns in oxygen to make water.\n2H₂ + O₂ → 2H₂O\nThe table shows some bond energies.\nH–H: 436 kJ/mol   O=O: 498 kJ/mol   O–H: 464 kJ/mol\n\nCalculate the energy change for the reaction and state whether the reaction is exothermic or endothermic.`, marks: 4, command: 'Calculate', markScheme: `• Energy to break bonds = (2 × 436) + 498 = 1370 (kJ/mol) (1)\n• Energy released making bonds = 4 × 464 = 1856 (kJ/mol) (1)\n• Energy change = 1370 − 1856 = −486 (kJ/mol) (1)\n• Exothermic, because more energy is released making bonds than is taken in breaking bonds / energy change is negative (1)\nALLOW ECF for the third and fourth marks\nALLOW 486 kJ/mol given out for the third mark\nCommon error: using 1 × H–H and 2 × O–H (436 + 498 − 928 = +6) scores 0 for marks 1–3; ALLOW ECF for the fourth mark` },
      { q: `A student reacts zinc with hydrochloric acid to make zinc chloride.\nZn + 2HCl → ZnCl₂ + H₂\nThe student uses 3.27 g of zinc and an acid solution containing 0.0800 mol of HCl.\nRelative atomic masses (Aᵣ): Cl = 35.5  Zn = 65.4\n\nIdentify the limiting reactant and calculate the maximum mass of zinc chloride that can be made.`, marks: 4, command: 'Calculate', markScheme: `• Moles of Zn = 3.27 ÷ 65.4 = 0.0500 (mol) (1)\n• 0.0500 mol Zn needs 0.100 mol HCl but only 0.0800 mol is present, so HCl is the limiting reactant (1)\n• Moles of ZnCl₂ = 0.0800 ÷ 2 = 0.0400 (mol) (1)\n• Mass of ZnCl₂ = 0.0400 × 136.4 = 5.46 (g) (1)\nALLOW ECF throughout\nIf zinc is wrongly identified as limiting, ALLOW ECF: 0.0500 × 136.4 = 6.82 g for marks 3 and 4 (max 3)` },
      { q: `A student burns aluminium powder in oxygen to make aluminium oxide.\nThe student finds that 1.08 g of aluminium reacts with 0.96 g of oxygen, O₂, to make 2.04 g of aluminium oxide, Al₂O₃.\nRelative atomic masses (Aᵣ): O = 16.0  Al = 27.0\n\nUse these masses to work out the balanced symbol equation for the reaction.`, marks: 4, command: 'Use', markScheme: `• Moles of Al = 1.08 ÷ 27.0 = 0.0400 (mol) (1)\n• Moles of O₂ = 0.96 ÷ 32.0 = 0.0300 (mol) and moles of Al₂O₃ = 2.04 ÷ 102.0 = 0.0200 (mol) (1)\n• Ratio Al : O₂ : Al₂O₃ = 0.04 : 0.03 : 0.02 = 4 : 3 : 2 (1)\n• 4Al + 3O₂ → 2Al₂O₃ (1)\nALLOW ECF from incorrect mole values for the ratio mark\nCorrect balanced equation with no working scores 1 mark only` },
      { q: `Zinc sulfate, ZnSO₄, is a soluble salt. It is made by reacting zinc oxide, an insoluble base, with dilute sulfuric acid.\nZnO(s) + H₂SO₄(aq) → ZnSO₄(aq) + H₂O(l)\nA student wants to make a pure, dry sample of zinc sulfate crystals.\n\nDescribe a method the student can use. Explain why each step is needed and how the student can work safely.*`, marks: 6, command: 'Describe', markScheme: `Level 3 (5–6 marks)\nDescribes a full, logically ordered method that would produce pure, dry crystals of zinc sulfate AND explains why most key steps are needed AND includes a relevant safety precaution.\nThere is a well-developed line of reasoning which is clear and logically structured. The information presented is relevant and substantiated.\n\nLevel 2 (3–4 marks)\nDescribes a method that would produce zinc sulfate crystals, with some steps explained OR a full method with few explanations.\nThere is a line of reasoning presented with some structure. The information presented is relevant and supported by some evidence.\n\nLevel 1 (1–2 marks)\nDescribes some relevant steps, e.g. mixing zinc oxide with acid OR filtering OR heating the solution.\nThere is an attempt at a logical structure with a line of reasoning. The information is in the most part relevant.\n\n0 marks\nNo response or no response worthy of credit.\n\nIndicative scientific points may include:\nMethod\n• measure a volume of dilute sulfuric acid into a beaker\n• warm the acid gently (do not boil)\n• add zinc oxide a spatula at a time, stirring, until no more dissolves / excess solid remains\n• filter the mixture to remove the excess zinc oxide\n• heat the filtrate in an evaporating basin to evaporate some of the water / until crystals start to form\n• leave the solution to cool and crystallise\n• filter off / pour off the crystals and dry them between filter paper or in a warm oven / desiccator\nExplanations\n• warming speeds up the reaction\n• excess zinc oxide makes sure all the acid has reacted / no acid is left in the product\n• filtering removes unreacted zinc oxide because it is insoluble\n• evaporating only part of the water and cooling slowly gives larger, purer crystals; heating to dryness may decompose the salt / give a powder\n• drying removes water from the surface of the crystals\nSafety\n• wear eye protection because sulfuric acid is an irritant / corrosive\n• do not boil the acid / heat gently to avoid spitting` }
    ]
  },
  'C4': {
    name: 'Predicting and Identifying Reactions and Products',
    questions: [
      { q: `This question is about the Group 1 metals.\n\nA teacher adds a small piece of sodium to a trough of water. The water contains a few drops of universal indicator, which is green at the start.\n\nState the colour of the universal indicator at the end of the reaction.`, marks: 1, command: 'State', markScheme: `• Purple / blue / violet (1)\n\nALLOW dark blue\nIGNORE green / red / orange` },
      { q: `This question is about the Group 0 elements.\n\nThe table shows the boiling points of some Group 0 elements.\n\nElement | Boiling point (°C)\nHelium | −269\nNeon | −246\nArgon | −186\nKrypton | ……\nXenon | −108\n\nPredict the boiling point of krypton.`, marks: 1, command: 'Predict', markScheme: `• Any value between −185 °C and −109 °C (1)\n\n(The actual value is −153 °C.)\nDO NOT ALLOW a value outside the range or a positive value` },
      { q: `A student adds a piece of magnesium ribbon to dilute hydrochloric acid in a test tube. The mixture fizzes.\n\nThe student holds a lighted splint at the mouth of the test tube and hears a squeaky pop.\n\nName the gas made in the reaction.`, marks: 1, command: 'Name', markScheme: `• Hydrogen (1)\n\nALLOW H₂\nDO NOT ALLOW H / H⁺` },
      { q: `Ammonia is made in industry by the Haber process. The reaction uses a transition metal as a catalyst.\n\nN₂ + 3H₂ ⇌ 2NH₃\n\nName the transition metal used as the catalyst in the Haber process.`, marks: 1, command: 'Name', markScheme: `• Iron (1)\n\nALLOW Fe\nIGNORE iron oxide` },
      { q: `A student tests a solution for halide ions. She adds dilute nitric acid and then a few drops of silver nitrate solution.\n\nA yellow precipitate forms.\n\nIdentify the halide ion in the solution.`, marks: 1, command: 'Identify', markScheme: `• Iodide (ion) (1)\n\nALLOW I⁻\nDO NOT ALLOW iodine / I / I₂` },
      { q: `A water company tests drinking water for very small amounts of metal ions. It uses an instrumental method called flame emission spectroscopy rather than flame tests.\n\nGive one advantage of using an instrumental method rather than a flame test.`, marks: 1, command: 'Give', markScheme: `Any one from:\n• More sensitive / can detect very small amounts / very low concentrations (1)\n• More accurate (1)\n• Faster / quicker / can be automated (1)\n• Can identify ions in a mixture (1)\n• Can measure the concentration (as well as identify the ion) (1)\n\nIGNORE easier / cheaper / more reliable on its own` },
      { q: `The table shows the melting points of some Group 1 metals.\n\nMetal | Melting point (°C)\nLithium | 181\nSodium | 98\nPotassium | 63\nRubidium | 39\nCaesium | 28\n\nDescribe the trend in melting point down Group 1.\nUse the data to predict the state of rubidium at 45 °C.`, marks: 2, command: 'Describe', markScheme: `• Melting point decreases down the group (1)\n• (Rubidium is a) liquid (at 45 °C) (1)\n\nALLOW ORA for the trend (melting point increases up the group)\nIGNORE references to boiling point` },
      { q: `Potassium is stored under oil. A teacher cuts a small piece of potassium and adds it to cold water. The potassium moves around on the surface and burns with a lilac flame.\n\nComplete the word equation for the reaction.\n\npotassium + water → …………… + ……………`, marks: 2, command: 'Complete', markScheme: `• Potassium hydroxide (1)\n• Hydrogen (1)\n\nEither order\nDO NOT ALLOW potassium oxide\nALLOW formulae KOH and H₂` },
      { q: `Freshly cut lithium is shiny. The surface goes dull quickly in air because the lithium reacts with oxygen to make lithium oxide.\n\nComplete the balanced symbol equation for this reaction.\n\n……Li + O₂ → ……………`, marks: 2, command: 'Complete', markScheme: `• Correct formula of the product: Li₂O (1)\n• Correct balancing: 4Li + O₂ → 2Li₂O (1)\n\nThe balancing mark depends on the correct formula Li₂O\nALLOW multiples` },
      { q: `A teacher heats a small piece of sodium in a combustion spoon until it starts to burn. The teacher then lowers it into a gas jar of chlorine in a fume cupboard.\n\nSodium chloride is made.\n\nDescribe two observations the teacher would see during the reaction.`, marks: 2, command: 'Describe', markScheme: `Any two from:\n• Sodium burns brightly / with a bright flame (1)\n• Yellow / orange flame (1)\n• White solid / white powder / white smoke forms (1)\n• Green colour of the chlorine fades / disappears (1)\n\nIGNORE fizzing / bubbles\nIGNORE "sodium chloride forms" (not an observation)` },
      { q: `The table shows information about some Group 7 elements.\n\nElement | State at room temperature | Colour\nFluorine | gas | pale yellow\nChlorine | gas | green\nBromine | liquid | red-brown\nIodine | solid | grey-black\nAstatine | …… | ……\n\nPredict the state and colour of astatine at room temperature.`, marks: 2, command: 'Predict', markScheme: `• Solid (1)\n• Black / very dark grey (1)\n\nALLOW dark brown-black / dark colour for the second mark\nDO NOT ALLOW a lighter colour than iodine` },
      { q: `A student adds bromine water to two test tubes. One contains potassium chloride solution and the other contains potassium iodide solution.\n\nThe solution in the potassium iodide tube turns brown. There is no change in the potassium chloride tube.\n\nExplain why there is no reaction between bromine and potassium chloride.`, marks: 2, command: 'Explain', markScheme: `• Bromine is less reactive than chlorine (1)\n• So bromine cannot displace chlorine / chloride from its compound (1)\n\nALLOW ORA: chlorine is more reactive than bromine\nALLOW "a less reactive halogen cannot displace a more reactive halogen"\nDO NOT ALLOW bromide / bromine ions in the first marking point` },
      { q: `Chlorine is bubbled through colourless sodium bromide solution. The solution turns orange.\n\nComplete the word equation for this reaction.\n\nchlorine + sodium bromide → …………… + ……………`, marks: 2, command: 'Complete', markScheme: `• Sodium chloride (1)\n• Bromine (1)\n\nEither order\nALLOW NaCl and Br₂\nDO NOT ALLOW bromide for bromine` },
      { q: `Argon is a Group 0 element. Argon atoms have the electronic structure 2.8.8.\n\nExplain why argon is unreactive.\nUse ideas about electrons in your answer.`, marks: 2, command: 'Explain', markScheme: `• Argon has a full / stable outer shell (of electrons) (1)\n• So it does not easily lose, gain or share electrons (1)\n\nALLOW "has 8 electrons in its outer shell" for the first mark\nIGNORE "does not need to react"\nDO NOT ALLOW full shells (must be outer shell)` },
      { q: `Old-style filament light bulbs are filled with argon instead of air. The tungsten filament gets very hot when the bulb is switched on.\n\nExplain why the bulb is filled with argon instead of air.`, marks: 2, command: 'Explain', markScheme: `• Argon is unreactive / inert (1)\n• Air contains oxygen which would react with / oxidise / burn the hot filament (1)\n\nALLOW "argon stops the filament burning / oxidising" for 1 mark only if no reference to oxygen in air` },
      { q: `The table shows information about four metals, A, B, C and D (data written for this practice question).\n\nMetal | Melting point (°C) | Density (g/cm³) | Colour of compounds\nA | 98 | 0.97 | white\nB | 1538 | 7.9 | green or orange-brown\nC | 650 | 1.7 | white\nD | 1085 | 9.0 | blue or green\n\nWhich two metals are transition metals?\nGive a reason for your answer.`, marks: 2, command: 'Identify', markScheme: `• B and D (1)\n• They form coloured compounds / have high melting points / high densities (1)\n\nBoth letters needed for the first mark\nALLOW "they have more than one colour of compound / form ions with different charges"` },
      { q: `Iron is a transition metal. Iron reacts with chlorine to make iron chloride. Iron can form two different chlorides: FeCl₂ and FeCl₃.\n\nChloride ions have the formula Cl⁻.\n\nState the charge on the iron ion in FeCl₂ and in FeCl₃.`, marks: 2, command: 'State', markScheme: `• FeCl₂: 2+ / Fe²⁺ (1)\n• FeCl₃: 3+ / Fe³⁺ (1)\n\nALLOW +2 and +3\nDO NOT ALLOW 2 or 3 without a sign` },
      { q: `A student adds pieces of four metals, W, X, Y and Z, to dilute hydrochloric acid. The pieces are the same size. The student records the results.\n\nMetal | Observation\nW | a few bubbles form slowly\nX | no bubbles\nY | very fast fizzing, metal disappears quickly\nZ | steady fizzing\n\nPut the metals in order of reactivity.\nExplain how you decided.`, marks: 2, command: 'Deduce', markScheme: `• Y > Z > W > X (most reactive first) (1)\n• The faster the fizzing / the more bubbles (of hydrogen), the more reactive the metal (1)\n\nALLOW ORA for the order if clearly labelled least to most reactive\nALLOW "X does not react so is least reactive" as the explanation` },
      { q: `A student puts an iron nail into magnesium sulfate solution and another iron nail into copper sulfate solution.\n\nThe nail in copper sulfate solution becomes coated with a brown solid. There is no change to the nail in magnesium sulfate solution.\n\nExplain why there is no reaction with magnesium sulfate solution.`, marks: 2, command: 'Explain', markScheme: `• Iron is less reactive than magnesium (1)\n• So iron cannot displace magnesium (from its compound / solution) (1)\n\nALLOW ORA: magnesium is more reactive than iron\nIGNORE references to copper` },
      { q: `During the electrolysis of sodium chloride solution, a gas is made at the anode. A student thinks the gas is chlorine.\n\nDescribe a test the student can do to show that the gas is chlorine.\nGive the result.`, marks: 2, command: 'Describe', markScheme: `• (Hold) damp / moist (blue) litmus paper in the gas (1)\n• It is bleached / turns white (1)\n\nALLOW damp universal indicator paper\nALLOW blue litmus turns red then white\nThe result mark depends on litmus or indicator paper\nIGNORE "goes colourless"\nDO NOT ALLOW dry litmus paper for the first mark` },
      { q: `A student does flame tests on some metal compounds. The table shows the results.\n\nCompound | Flame colour\nlithium chloride | ……\nsodium chloride | yellow\ncalcium chloride | orange-red\ncopper chloride | ……\n\nComplete the table.`, marks: 2, command: 'Complete', markScheme: `• Lithium chloride: red / crimson (1)\n• Copper chloride: green / blue-green (1)\n\nALLOW scarlet for lithium\nDO NOT ALLOW orange-red / brick red for lithium\nIGNORE blue on its own for copper` },
      { q: `A student does a flame test on a solid. The solid is a mixture of sodium chloride and potassium chloride.\n\nThe flame is yellow. The student concludes that the solid only contains sodium ions.\n\nExplain why the student's conclusion is wrong.`, marks: 2, command: 'Explain', markScheme: `• Potassium gives a lilac flame (1)\n• The yellow (sodium) colour masks / hides / is brighter than the lilac colour (1)\n\nALLOW "the colours mix / one colour covers the other" for the second mark\nIGNORE references to contamination` },
      { q: `A student adds a few drops of sodium hydroxide solution to a solution of iron(II) sulfate, FeSO₄.\n\nA precipitate forms.\n\nState the colour of the precipitate and name the precipitate.`, marks: 2, command: 'State', markScheme: `• Green (1)\n• Iron(II) hydroxide (1)\n\nALLOW Fe(OH)₂ for the name\nALLOW grey-green / dark green\nDO NOT ALLOW orange-brown / blue\nDO NOT ALLOW iron(III) hydroxide / iron oxide` },
      { q: `To test a solution for sulfate ions, a student adds dilute hydrochloric acid and then barium chloride solution. A white precipitate shows sulfate ions are present.\n\nExplain why the student adds dilute hydrochloric acid before the barium chloride solution.`, marks: 2, command: 'Explain', markScheme: `• To remove / react with carbonate ions (1)\n• Carbonate ions would also give a white precipitate (with barium ions) / give a false positive result (1)\n\nALLOW "barium carbonate is also a white solid"\nIGNORE "to make it acidic" on its own` },
      { q: `Chlorine displaces bromine from potassium bromide solution.\n\nCl₂ + 2KBr → 2KCl + Br₂\n\nWrite the ionic equation for this reaction.`, marks: 2, command: 'Write', markScheme: `• Correct species: Cl₂ + Br⁻ → Cl⁻ + Br₂ (1)\n• Correct balancing: Cl₂ + 2Br⁻ → 2Cl⁻ + Br₂ (1)\n\nALLOW multiples\nIGNORE state symbols\nIf K⁺ is shown on both sides, award 1 mark only` },
      { q: `A student adds magnesium powder to copper sulfate solution in a polystyrene cup. She measures the temperature rise. She does the experiment three times (data written for this practice question).\n\nExperiment | 1 | 2 | 3\nTemperature rise (°C) | 24.5 | 18.0 | 25.0\n\nCalculate the mean temperature rise.\nIgnore any anomalous result.`, marks: 2, command: 'Calculate', markScheme: `FIRST CHECK THE ANSWER ON THE ANSWER LINE\nIf answer = 24.75 / 24.8 (°C) award 2 marks\n\n• Identifies experiment 2 (18.0) as anomalous / uses only 24.5 and 25.0 (1)\n• (24.5 + 25.0) ÷ 2 = 24.75 (°C) (1)\n\nALLOW 24.8\nIf all three values used: (24.5 + 18.0 + 25.0) ÷ 3 = 22.5 award 1 mark` },
      { q: `A scientist uses flame emission spectroscopy to analyse a sample. The table shows the wavelengths of the main lines in the spectra of some metal ions and in the spectrum of the sample (simplified data written for this practice question).\n\nSpectrum | Wavelengths of lines (nm)\nlithium | 610, 671\nsodium | 589\npotassium | 404, 767\ncalcium | 423\nsample | 404, 589, 767\n\nWhich metal ions are in the sample?\nExplain your answer.`, marks: 2, command: 'Identify', markScheme: `• Sodium and potassium (1)\n• All of the lines for sodium and potassium are in the sample's spectrum / lines at 589 nm and at 404 and 767 nm match (and there are no lines at 610, 671 or 423 nm) (1)\n\nBoth ions needed for the first mark\nDO NOT ALLOW the first mark if lithium or calcium is included` },
      { q: `A teacher shows a class how lithium, sodium and potassium react with water.\n\nLithium fizzes steadily. Sodium fizzes quickly and melts into a ball. Potassium reacts very quickly and the hydrogen catches fire.\n\nRubidium is below potassium in Group 1.\n\nPredict how rubidium reacts with water. Include the names of the products in your answer.`, marks: 3, command: 'Predict', markScheme: `• Reacts more vigorously / faster than potassium / explodes (1)\n• Makes hydrogen (1)\n• Makes rubidium hydroxide / an alkaline solution (1)\n\nALLOW RbOH and H₂\nALLOW "very violently"\nDO NOT ALLOW rubidium oxide` },
      { q: `A student adds solutions of chlorine, bromine and iodine to solutions of potassium halides. The results show that the reactivity of the halogens decreases down Group 7.\n\nExplain why the reactivity of the halogens decreases down Group 7.\nUse ideas about electrons in your answer.`, marks: 3, command: 'Explain', markScheme: `• Halogens react by gaining one electron (to fill the outer shell) (1)\n• Down the group the outer shell is further from the nucleus / atoms are larger / there are more shells (1)\n• So the attraction (of the nucleus) for the extra electron is weaker / it is harder to gain an electron (1)\n\nALLOW more shielding for the second marking point\nIGNORE references to losing electrons\nDO NOT ALLOW "harder to lose an electron"` },
      { q: `Sodium reacts with chlorine to make sodium chloride.\n\n2Na + Cl₂ → 2NaCl\n\nA teacher reacts 0.46 g of sodium with excess chlorine.\n\nCalculate the mass of sodium chloride made.\nRelative atomic mass (Aᵣ): Na = 23.0  Cl = 35.5`, marks: 3, command: 'Calculate', markScheme: `FIRST CHECK THE ANSWER ON THE ANSWER LINE\nIf answer = 1.17 (g) award 3 marks\n\n• Moles of sodium = 0.46 ÷ 23.0 = 0.020 (mol) (1)\n• Mᵣ of NaCl = 23.0 + 35.5 = 58.5 (1)\n• Mass of NaCl = 0.020 × 58.5 = 1.17 (g) (1)\n\nALLOW ecf from an incorrect Mᵣ\nALLOW the ratio method: 46 g Na → 117 g NaCl, so 0.46 g → 1.17 g` },
      { q: `A student adds small pieces of four metals to solutions of their sulfates. A tick (✓) means a reaction happened. A cross (✗) means no reaction. A dash (–) means the test was not done.\n\nMetal | copper sulfate | iron sulfate | magnesium sulfate | zinc sulfate\ncopper | – | ✗ | ✗ | ✗\niron | ✓ | – | ✗ | ✗\nmagnesium | ✓ | ✓ | – | ✓\nzinc | ✓ | ✓ | ✗ | –\n\nDeduce the order of reactivity of the four metals.\nExplain how you used the results.`, marks: 3, command: 'Deduce', markScheme: `• Magnesium > zinc > iron > copper (most reactive first) (1)\n• A more reactive metal displaces a less reactive metal from a solution of its compound (1)\n• The metal with the most ticks is the most reactive / magnesium displaces all three, copper displaces none (1)\n\nALLOW ORA for the order if clearly labelled\nALLOW zinc is above iron because zinc displaces iron but iron does not displace zinc` },
      { q: `Magnesium reacts with copper sulfate solution.\n\nMg(s) + Cu²⁺(aq) → Mg²⁺(aq) + Cu(s)\n\nThis is a redox reaction.\n\nExplain why this reaction is a redox reaction.\nUse ideas about electrons in your answer.`, marks: 3, command: 'Explain', markScheme: `• Magnesium (atoms) lose (two) electrons / Mg → Mg²⁺ + 2e⁻ (1)\n• So magnesium is oxidised (1)\n• Copper ions gain (two) electrons / Cu²⁺ + 2e⁻ → Cu, so copper ions are reduced (1)\n\nOxidation and reduction must be linked to loss and gain of electrons\nDO NOT ALLOW references to oxygen gain or loss for any mark` },
      { q: `A student has a white powder. She thinks it might be a carbonate.\n\nDescribe how she can test the powder to show it contains carbonate ions.\nGive the result she would see if carbonate ions are present.`, marks: 3, command: 'Describe', markScheme: `• Add (dilute) acid / hydrochloric acid (1)\n• Fizzing / effervescence / bubbles (1)\n• Bubble the gas through limewater, which turns milky / cloudy (1)\n\nALLOW "the gas is carbon dioxide" only if the limewater test is described\nDO NOT ALLOW "limewater turns colourless / clear"` },
      { q: `A white solid gives a lilac flame in a flame test.\n\nThe student dissolves the solid in water. She adds dilute hydrochloric acid and then barium chloride solution. A white precipitate forms.\n\nIdentify the solid.\nExplain your answer.`, marks: 3, command: 'Identify', markScheme: `• Lilac flame shows potassium ions (1)\n• White precipitate with barium chloride shows sulfate ions (1)\n• Potassium sulfate / K₂SO₄ (1)\n\nALLOW the third mark as ecf from one incorrect ion\nDO NOT ALLOW potassium sulfide / sulfite` },
      { q: `A technician has three bottles of solution with no labels. One contains copper(II) sulfate, one contains iron(II) sulfate and one contains iron(III) sulfate.\n\nThe technician adds a few drops of sodium hydroxide solution to a sample from each bottle.\n\nDescribe how the results show which solution is in each bottle.`, marks: 3, command: 'Describe', markScheme: `• Copper(II) sulfate gives a blue precipitate (1)\n• Iron(II) sulfate gives a green precipitate (1)\n• Iron(III) sulfate gives an orange-brown precipitate (1)\n\nALLOW red-brown / brown / rust-coloured for iron(III)\nALLOW pale blue / light blue for copper(II)\nIf "precipitate" or "solid" is not used anywhere, award a maximum of 2 marks` },
      { q: `A water company wants to check that tap water contains chloride ions.\n\nDescribe a chemical test to show that chloride ions are present.\nGive the result.`, marks: 3, command: 'Describe', markScheme: `• Add (dilute) nitric acid (1)\n• Add silver nitrate solution (1)\n• White precipitate (1)\n\nALLOW acidified silver nitrate for the first two marks\nDO NOT ALLOW hydrochloric acid for the first mark\nIGNORE cloudy on its own for the third mark` },
      { q: `A student has two test tubes of colourless gas. One contains oxygen and the other contains carbon dioxide. The test tubes are not labelled.\n\nDescribe tests the student can do to show which test tube contains each gas.\nGive the result for each test.`, marks: 4, command: 'Describe', markScheme: `• Oxygen: put in a glowing splint (1)\n• The splint relights (1)\n• Carbon dioxide: bubble the gas through / shake with limewater (1)\n• The limewater turns milky / cloudy (1)\n\nDO NOT ALLOW lighted / burning splint for oxygen\nALLOW "the splint goes out" as an additional observation for carbon dioxide but it does not score on its own\nDO NOT ALLOW "limewater turns colourless / clear"` },
      { q: `A student tests two solids, P and Q. The table shows the results.\n\nTest | Solid P | Solid Q\nflame test | green flame | no clear colour\nadd sodium hydroxide solution to a solution of the solid | blue precipitate | orange-brown precipitate\nadd dilute nitric acid then silver nitrate solution | white precipitate | no change\nadd dilute hydrochloric acid then barium chloride solution | no change | white precipitate\n\nIdentify solids P and Q.\nExplain your answers.`, marks: 4, command: 'Identify', markScheme: `• P contains copper(II) ions: green flame / blue precipitate (1)\n• P contains chloride ions: white precipitate with silver nitrate, so P is copper(II) chloride / CuCl₂ (1)\n• Q contains iron(III) ions: orange-brown precipitate (1)\n• Q contains sulfate ions: white precipitate with barium chloride, so Q is iron(III) sulfate / Fe₂(SO₄)₃ (1)\n\nALLOW copper chloride for P\nALLOW iron sulfate for Q only if iron(III) ions are identified elsewhere\nALLOW correct ions identified with a correct reason for each marking point` },
      { q: `The table shows some properties of sodium and iron.\n\nProperty | Sodium | Iron\nmelting point (°C) | 98 | 1538\ndensity (g/cm³) | 0.97 | 7.87\nreaction with cold water | fizzes quickly, makes hydrogen | no reaction (rusts slowly with water and oxygen)\ncolour of compounds | white | green or orange-brown\nused as a catalyst | no | yes\n\nSodium is a Group 1 metal. Iron is a transition metal.\n\nCompare the properties of Group 1 metals and transition metals.\nUse the data in the table.`, marks: 4, command: 'Compare', markScheme: `Any four from:\n• Transition metals have (much) higher melting points (1)\n• Transition metals have (much) higher densities / Group 1 metals have low density (can float on water) (1)\n• Group 1 metals are (much) more reactive / react with cold water but transition metals do not (1)\n• Transition metals form coloured compounds but Group 1 compounds are white (1)\n• Transition metals (and their compounds) are used as catalysts but Group 1 metals are not (1)\n• Transition metals form ions with different charges / Group 1 metals only form 1+ ions (1)\n\nEach point must be a comparison\nALLOW correct comparisons quoting data, e.g. "iron melts at 1440 °C higher than sodium"` },
      { q: `A student wants to find the order of reactivity of chlorine, bromine and iodine.\n\nShe has:\n• chlorine water, bromine water and iodine solution\n• potassium chloride, potassium bromide and potassium iodide solutions\n• test tubes and dropping pipettes.\n\nChlorine water is pale green, bromine water is orange and iodine solution is brown. The potassium halide solutions are colourless.\n\nDescribe how the student can use these chemicals to find the order of reactivity of the halogens. Include the results she should expect and explain how they show the order of reactivity.*`, marks: 6, command: 'Describe', markScheme: `Level 3 (5–6 marks)\nA detailed method that tests each halogen with the halide solutions AND gives correct expected results for all combinations AND explains how the results show the order of reactivity (Cl > Br > I), linked to displacement.\nThere is a well-developed line of reasoning which is clear and logically structured. The information presented is relevant and substantiated.\n\nLevel 2 (3–4 marks)\nA method that tests halogens with halide solutions AND gives some correct expected results AND states the order of reactivity.\nThere is a line of reasoning presented with some structure. The information presented is relevant and supported by some evidence.\n\nLevel 1 (1–2 marks)\nA simple method OR some correct results OR the correct order of reactivity.\nThere is an attempt at a logical structure with a line of reasoning. The information is in the most part relevant.\n\n0 marks\nNo response or no response worthy of credit.\n\nIndicative scientific points may include:\n\nMethod\n• Put a few cm³ of each potassium halide solution into separate test tubes\n• Add a few drops of each halogen solution to each halide solution (not its own halide)\n• Look for a colour change / compare with the colour of the halogen solution added\n• Use the same volumes each time / shake to mix\n• Work in a well-ventilated room / wear eye protection (halogens are toxic / harmful)\n\nResults\n• Chlorine + potassium bromide: turns orange (bromine made)\n• Chlorine + potassium iodide: turns brown (iodine made)\n• Bromine + potassium iodide: turns brown (iodine made)\n• Bromine + potassium chloride: no change (stays orange)\n• Iodine + potassium chloride / potassium bromide: no change (stays brown)\n\nExplanation\n• A more reactive halogen displaces a less reactive halogen from a solution of its salt\n• Chlorine displaces bromine and iodine so it is the most reactive\n• Iodine does not displace either so it is the least reactive\n• Order: chlorine > bromine > iodine\n• e.g. Cl₂ + 2KBr → 2KCl + Br₂ / Cl₂ + 2Br⁻ → 2Cl⁻ + Br₂` }
    ]
  },
  'C5': {
    name: 'Monitoring and Controlling Chemical Reactions',
    questions: [
      { q: `A student does a titration to find the volume of dilute hydrochloric acid needed to neutralise 25.0 cm³ of sodium hydroxide solution. The sodium hydroxide solution and a few drops of indicator are in a conical flask.\n\nName the piece of apparatus the student uses to add the hydrochloric acid to the flask a little at a time.`, marks: 1, command: 'Name', markScheme: `• Burette (1)\nDo not allow: pipette / measuring cylinder / dropping pipette` },
      { q: `A student investigates the reaction between magnesium ribbon and dilute hydrochloric acid. The student measures the volume of hydrogen gas made, in cm³, and the time taken, in s.\n\nWhat is the unit for the rate of this reaction?`, marks: 1, command: 'What', markScheme: `• cm³/s (1)\nAllow: cm³ s⁻¹ / cm³ per second\nDo not allow: cm³ or s on their own` },
      { q: `A student heats a small amount of white solid ammonium chloride in a test tube. The solid breaks down into ammonia gas and hydrogen chloride gas. Near the cool top of the test tube the two gases react to form white solid ammonium chloride again.\n\nammonium chloride ⇌ ammonia + hydrogen chloride\n\nWhat type of reaction is this?`, marks: 1, command: 'What', markScheme: `• Reversible (reaction) (1)\nIgnore: thermal decomposition / endothermic on its own` },
      { q: `A student adds 0.50 g of manganese(IV) oxide to hydrogen peroxide solution. Bubbles of oxygen are given off quickly. At the end of the reaction the student filters off the manganese(IV) oxide, dries it and weighs it.\n\nThe manganese(IV) oxide is a catalyst.\n\nPredict the mass of dry manganese(IV) oxide the student collects.`, marks: 1, command: 'Predict', markScheme: `• 0.50 g (1)\nAllow: the same mass as at the start` },
      { q: `A student investigates how temperature affects the rate of reaction between sodium thiosulfate solution and dilute hydrochloric acid. The flask is placed on a paper cross. The student times how long it takes for the cross to disappear as a yellow precipitate forms.\n\nGive one reason why the student should use the same paper cross for every experiment.`, marks: 1, command: 'Give', markScheme: `• So the cross disappears when the same amount of precipitate has formed / so the test is fair / so the end point is judged the same way each time (1)\nAllow: a different cross may be darker or larger so would take a different time to disappear` },
      { q: `Nitrogen and hydrogen react in a closed container to make ammonia.\n\nN₂(g) + 3H₂(g) ⇌ 2NH₃(g)\n\nAfter some time the reaction reaches dynamic equilibrium.\n\nWhat can you say about the rates of the forward reaction and the backward reaction at dynamic equilibrium?`, marks: 1, command: 'What', markScheme: `• The rates are equal / the same (1)\nDo not allow: both reactions have stopped` },
      { q: `A student dissolves 5.0 g of copper sulfate in water. The student makes the solution up to 200 cm³ in a volumetric flask.\n\nCalculate the concentration of the copper sulfate solution in g/dm³.`, marks: 2, command: 'Calculate', markScheme: `• Volume = 200 ÷ 1000 = 0.200 dm³ (1)\n• Concentration = 5.0 ÷ 0.200 = 25 g/dm³ (1)\nAward 2 marks for a correct answer with no working.\nAllow: 1 mark for 0.025 (volume not converted)` },
      { q: `A technician needs to make 100 cm³ of sodium carbonate solution with a concentration of 0.500 mol/dm³.\n\nCalculate the mass of sodium carbonate, Na₂CO₃, the technician must dissolve.\n\nRelative formula mass (Mᵣ): Na₂CO₃ = 106.0`, marks: 2, command: 'Calculate', markScheme: `• Amount = 0.500 × (100 ÷ 1000) = 0.0500 mol (1)\n• Mass = 0.0500 × 106.0 = 5.30 g (1)\nAward 2 marks for a correct answer with no working.\nAllow: 5.3 g` },
      { q: `A student does a titration. The table shows the student's results (data written for this practice question).\n\nTitration | Rough | 1 | 2 | 3\nVolume of acid added (cm³) | 21.10 | 20.60 | 20.10 | 20.20\n\nConcordant results are within 0.10 cm³ of each other.\n\nCalculate the mean titre. Use only the concordant results.`, marks: 2, command: 'Calculate', markScheme: `• Selects titrations 2 and 3 only (20.10 and 20.20) (1)\n• Mean = (20.10 + 20.20) ÷ 2 = 20.15 cm³ (1)\nAward 2 marks for 20.15 cm³ with no working.\nDo not allow: 20.30 (all three accurate titres used) or 20.50 (rough included) for the second mark` },
      { q: `A student fills a burette with dilute sulfuric acid for a titration. The student reads the burette at the start and at the end of the titration.\n\nDescribe two things the student should do to make sure the burette readings are accurate.`, marks: 2, command: 'Describe', markScheme: `Any two from:\n• Read at eye level / with the eye level with the meniscus (1)\n• Read from the bottom of the meniscus (1)\n• Rinse the burette with the sulfuric acid (not water) before filling (1)\n• Make sure the jet / tip below the tap is filled / has no air bubble before the first reading (1)\n• Remove the funnel before taking the reading (1)\n• Clamp the burette vertically (1)` },
      { q: `Calcium carbonate reacts with dilute hydrochloric acid to make carbon dioxide gas. A student collects 360 cm³ of carbon dioxide at room temperature and pressure (RTP).\n\nCalculate the amount, in moles, of carbon dioxide collected.\n\nOne mole of any gas occupies 24 dm³ at RTP.`, marks: 2, command: 'Calculate', markScheme: `• Volume = 360 ÷ 1000 = 0.360 dm³ OR molar volume = 24 000 cm³ (1)\n• Amount = 0.360 ÷ 24 = 0.015 mol (1)\nAward 2 marks for 0.015 mol with no working.\nAllow: 1.5 × 10⁻² mol` },
      { q: `Propane, C₃H₈, is used as a fuel for camping stoves. It burns completely in oxygen.\n\nC₃H₈(g) + 5O₂(g) → 3CO₂(g) + 4H₂O(l)\n\nA student burns 50 cm³ of propane gas. All gas volumes are measured at the same temperature and pressure.\n\nCalculate the volume of oxygen needed and the volume of carbon dioxide made.`, marks: 2, command: 'Calculate', markScheme: `• Oxygen: 5 × 50 = 250 cm³ (1)\n• Carbon dioxide: 3 × 50 = 150 cm³ (1)\nIgnore: any volume given for water (it is a liquid)` },
      { q: `A student makes copper sulfate crystals by reacting copper oxide with sulfuric acid. The student calculates that the maximum mass of crystals that can be made is 12.0 g. The student actually makes 9.6 g of crystals.\n\nCalculate the percentage yield.`, marks: 2, command: 'Calculate', markScheme: `• Percentage yield = (9.6 ÷ 12.0) × 100 (1)\n• = 80% (1)\nAward 2 marks for 80% with no working.` },
      { q: `A student makes a salt by neutralisation. The actual yield of the salt is less than the theoretical yield.\n\nGive two reasons why the actual yield is less than the theoretical yield.`, marks: 2, command: 'Give', markScheme: `Any two from:\n• Some product is lost when transferring between containers / when filtering / left on the filter paper (1)\n• The reaction may not go to completion / is reversible (1)\n• Side reactions / other products are made (1)\n• Some reactant may be impure (1)\n• Some product stays dissolved in the solution / not all crystallises (1)\nIgnore: human error / spillage without further explanation` },
      { q: `Hydrogen is made in industry by reacting methane with steam.\n\nCH₄ + H₂O → CO + 3H₂\n\nHydrogen is the only useful product.\n\nCalculate the atom economy for making hydrogen by this reaction.\n\nRelative formula masses (Mᵣ): CH₄ = 16.0  H₂O = 18.0  H₂ = 2.0`, marks: 2, command: 'Calculate', markScheme: `• Atom economy = (3 × 2.0) ÷ (16.0 + 18.0) × 100 OR 6.0 ÷ 34.0 × 100 (1)\n• = 17.6% (1)\nAward 2 marks for 17.6% / 18% with no working.\nAllow: 1 mark for 5.9% (3 not used for H₂)` },
      { q: `A student adds marble chips to excess dilute hydrochloric acid and collects the carbon dioxide gas in a gas syringe. In the first 20 s, 48 cm³ of gas is collected.\n\nCalculate the mean rate of reaction over the first 20 s.`, marks: 2, command: 'Calculate', markScheme: `• Mean rate = 48 ÷ 20 (1)\n• = 2.4 cm³/s (1)\nAward 2 marks for 2.4 cm³/s with no working.` },
      { q: `A student plots a graph of the volume of hydrogen made (y-axis, cm³) against time (x-axis, s) for the reaction between zinc and dilute sulfuric acid. The line is a curve.\n\nThe student draws a tangent to the curve at 20 s. The tangent passes through the points (0 s, 10 cm³) and (40 s, 70 cm³).\n\nCalculate the rate of reaction at 20 s.`, marks: 2, command: 'Calculate', markScheme: `• Gradient = (70 − 10) ÷ (40 − 0) (1)\n• = 1.5 cm³/s (1)\nAward 2 marks for 1.5 cm³/s with no working.` },
      { q: `In a sodium thiosulfate and hydrochloric acid experiment, a student times how long it takes for a cross under the flask to disappear. At 40 °C the cross disappears after 25 s.\n\nThe student calculates the relative rate of reaction using:\n\nrelative rate = 1 ÷ time\n\nCalculate the relative rate of reaction at 40 °C. Give the unit.`, marks: 2, command: 'Calculate', markScheme: `• 1 ÷ 25 = 0.04 (1)\n• Unit: s⁻¹ / /s (1)` },
      { q: `A student investigates how the concentration of hydrochloric acid affects the rate of reaction with magnesium ribbon. The student uses the same length of magnesium ribbon each time and measures the time for the magnesium to disappear.\n\nIdentify the independent variable and give one control variable in this investigation.`, marks: 2, command: 'Identify', markScheme: `• Independent variable: concentration of (hydrochloric) acid (1)\n• Control variable: any one from: volume of acid / temperature / length or mass of magnesium / surface area of magnesium (1)\nDo not allow: time taken as the control variable` },
      { q: `A student reacts calcium carbonate with dilute hydrochloric acid at 25 °C. Experiment 1 uses 2.0 mol/dm³ acid. Experiment 2 uses 0.5 mol/dm³ acid. All other conditions are the same. The reaction in Experiment 1 is faster.\n\nExplain why, in terms of particles and collisions.`, marks: 2, command: 'Explain', markScheme: `• In 2.0 mol/dm³ acid there are more (acid) particles in the same volume (1)\n• So there are more frequent collisions / more collisions per second (1)\nDo not allow: particles move faster / have more energy\nIgnore: "more collisions" without reference to time for the second mark` },
      { q: `Indigestion tablets contain calcium carbonate. They react with stomach acid. A student finds that a crushed tablet stops fizzing in acid much sooner than a whole tablet of the same mass.\n\nExplain why the crushed tablet reacts faster.`, marks: 2, command: 'Explain', markScheme: `• Crushed tablet has a larger surface area (to volume ratio) / more particles exposed to the acid (1)\n• So there are more frequent collisions (between acid particles and calcium carbonate particles) (1)\nDo not allow: bigger surface area with no indication it is the crushed tablet` },
      { q: `The enzyme amylase breaks down starch. A student measures the rate of reaction at different temperatures (data written for this practice question).\n\nTemperature (°C) | 20 | 30 | 40 | 50 | 60\nRelative rate | 0.4 | 0.7 | 1.0 | 0.3 | 0.0\n\nExplain why the rate is lower at 50 °C and 60 °C than at 40 °C.`, marks: 2, command: 'Explain', markScheme: `• The enzyme is denatured / the shape of the active site changes (at high temperature) (1)\n• So the starch / substrate no longer fits the active site (and cannot be broken down) (1)\nDo not allow: the enzyme is killed / dies` },
      { q: `Catalytic converters in car exhausts contain a platinum catalyst. The catalyst increases the rate of the reactions that change harmful gases into less harmful gases.\n\nExplain how a catalyst increases the rate of a reaction.`, marks: 2, command: 'Explain', markScheme: `• It provides an alternative reaction pathway / route (1)\n• with a lower activation energy (1)\nAllow: so more collisions / particles have enough energy to react (for the second mark only if lower activation energy is implied)\nDo not allow: the catalyst gives the particles more energy` },
      { q: `White anhydrous copper sulfate can be used to test for water.\n\nhydrated copper sulfate ⇌ anhydrous copper sulfate + water\n(blue)                              (white)\n\nThe forward reaction is endothermic.\n\nA student adds a few drops of water to some anhydrous copper sulfate. Describe what the student sees and state what happens to the temperature.`, marks: 2, command: 'Describe', markScheme: `• White solid turns blue (1)\n• The temperature rises / gets warmer (because the backward reaction is exothermic) (1)` },
      { q: `Ethanoic acid and ethanol react in a sealed flask to make ethyl ethanoate and water.\n\nethanoic acid + ethanol ⇌ ethyl ethanoate + water\n\nAfter a while the amounts of all four substances stop changing. The mixture is in dynamic equilibrium.\n\nExplain what is meant by dynamic equilibrium.`, marks: 2, command: 'Explain', markScheme: `• The forward and backward reactions are still happening / have not stopped (1)\n• at the same rate (so the concentrations stay the same) (1)\nIgnore: "in a closed system" on its own` },
      { q: `Chromate ions and dichromate ions are in equilibrium in solution.\n\n2CrO₄²⁻(aq) + 2H⁺(aq) ⇌ Cr₂O₇²⁻(aq) + H₂O(l)\n(yellow)                           (orange)\n\nA student adds a few drops of dilute acid to a yellow solution of the equilibrium mixture.\n\nPredict and explain what the student sees.`, marks: 2, command: 'Predict', markScheme: `• The solution turns (more) orange (1)\n• Increasing the concentration of H⁺ moves the position of equilibrium to the right / towards the products (to oppose the change / use up the added H⁺) (1)` },
      { q: `Dinitrogen tetroxide, N₂O₄, is a colourless gas. Nitrogen dioxide, NO₂, is a brown gas. They form an equilibrium in a sealed gas syringe.\n\nN₂O₄(g) ⇌ 2NO₂(g)\n\nThe student pushes in the plunger to increase the pressure. The student says that the position of equilibrium will move to the left.\n\nExplain why the student is correct.`, marks: 2, command: 'Explain', markScheme: `• There are fewer (gas) molecules / moles on the left (1 molecule) than on the right (2 molecules) (1)\n• Increasing pressure moves the equilibrium towards the side with fewer gas molecules (to reduce the pressure) (1)` },
      { q: `A student dissolves 2.00 g of sodium hydroxide, NaOH, in water and makes the solution up to 250 cm³.\n\nCalculate the concentration of the sodium hydroxide solution in mol/dm³.\n\nRelative formula mass (Mᵣ): NaOH = 40.0`, marks: 3, command: 'Calculate', markScheme: `• Amount of NaOH = 2.00 ÷ 40.0 = 0.0500 mol (1)\n• Volume = 250 ÷ 1000 = 0.250 dm³ (1)\n• Concentration = 0.0500 ÷ 0.250 = 0.200 mol/dm³ (1)\nAward 3 marks for 0.200 / 0.2 mol/dm³ with no working.\nAllow: 2 marks for 8.0 (g/dm³ calculated instead)` },
      { q: `A student titrates 25.0 cm³ of 0.100 mol/dm³ sodium hydroxide solution with dilute hydrochloric acid. The mean titre is 20.00 cm³.\n\nNaOH + HCl → NaCl + H₂O\n\nCalculate the concentration of the hydrochloric acid in mol/dm³.`, marks: 3, command: 'Calculate', markScheme: `• Moles of NaOH = 0.100 × (25.0 ÷ 1000) = 0.00250 mol (1)\n• Moles of HCl = 0.00250 mol (1 : 1 ratio) (1)\n• Concentration of HCl = 0.00250 ÷ (20.00 ÷ 1000) = 0.125 mol/dm³ (1)\nAward 3 marks for 0.125 mol/dm³ with no working.\nECF from an incorrect number of moles.` },
      { q: `A student reacts magnesium ribbon with excess dilute hydrochloric acid.\n\nMg + 2HCl → MgCl₂ + H₂\n\nThe student uses 0.243 g of magnesium.\n\nCalculate the volume of hydrogen gas, in cm³, made at room temperature and pressure (RTP).\n\nRelative atomic mass (Aᵣ): Mg = 24.3\nOne mole of any gas occupies 24 dm³ at RTP.`, marks: 3, command: 'Calculate', markScheme: `• Moles of Mg = 0.243 ÷ 24.3 = 0.0100 mol (1)\n• Moles of H₂ = 0.0100 mol (1 : 1 ratio) (1)\n• Volume = 0.0100 × 24 000 = 240 cm³ (1)\nAward 3 marks for 240 cm³ with no working.\nAllow: 2 marks for 0.24 (dm³ not converted to cm³)` },
      { q: `Ethanol, C₂H₅OH, can be made in two ways.\n\nMethod 1, fermentation: C₆H₁₂O₆ → 2C₂H₅OH + 2CO₂\nMethod 2, hydration of ethene: C₂H₄ + H₂O → C₂H₅OH\n\nThe atom economy of Method 2 is 100%.\n\nCalculate the atom economy of Method 1 and explain why Method 2 has a higher atom economy.\n\nRelative formula masses (Mᵣ): C₆H₁₂O₆ = 180.0  C₂H₅OH = 46.0`, marks: 3, command: 'Calculate', markScheme: `• Atom economy (Method 1) = (2 × 46.0) ÷ 180.0 × 100 (1)\n• = 51.1% (1)\n• Method 2 makes only one product / ethanol is the only product / no waste product, but Method 1 also makes carbon dioxide (as a by-product) (1)\nAllow: 51%` },
      { q: `A cube of a solid reactant has sides of 2 cm. It is cut into eight smaller cubes, each with sides of 1 cm.\n\nCalculate the surface area to volume ratio of the large cube and of the eight small cubes together, and use your answers to explain which reacts faster with acid.`, marks: 3, command: 'Calculate', markScheme: `• Large cube: surface area = 6 × 2 × 2 = 24 cm², volume = 8 cm³, ratio = 3 : 1 (1)\n• Eight small cubes: surface area = 8 × 6 × 1 × 1 = 48 cm², volume = 8 cm³, ratio = 6 : 1 (1)\n• The small cubes react faster because the larger surface area to volume ratio gives more frequent collisions (1)` },
      { q: `A student adds 1.00 g of large marble chips to excess dilute hydrochloric acid at 20 °C and records the volume of carbon dioxide made. The graph of volume of gas (y-axis, cm³) against time (x-axis, s) is a curve. It starts at 0, rises and then levels off at 240 cm³ after about 200 s.\n\nThe student repeats the experiment with 1.00 g of powdered marble. All other conditions stay the same.\n\nSketch both curves on one set of axes. Label them L (large chips) and P (powder).`, marks: 3, command: 'Sketch', diagram: true, markScheme: `• Curve P is steeper at the start than curve L (1)\n• Curve P levels off sooner / at an earlier time than curve L (1)\n• Both curves level off at the same final volume, 240 cm³ (1)\nCurve L must start at the origin and level off at 240 cm³ for any marks.` },
      { q: `Hydrogen peroxide decomposes slowly to make water and oxygen. The reaction is exothermic. Manganese(IV) oxide is a catalyst for this reaction.\n\n2H₂O₂ → 2H₂O + O₂\n\nDraw a reaction profile for this reaction. Label the activation energy. Show the pathway with the catalyst on the same diagram.`, marks: 3, command: 'Draw', diagram: true, markScheme: `• Products drawn at a lower energy than reactants, labelled (1)\n• Hump from reactants with activation energy labelled as the energy from the reactants to the top of the hump (1)\n• Second, lower hump labelled as the catalysed pathway, starting and finishing at the same levels (1)\nAxes must be energy (y) and progress of reaction (x) for full marks; ignore the absence of units.` },
      { q: `A student reacts sodium thiosulfate solution with dilute hydrochloric acid. At 20 °C the cross under the flask disappears after 80 s. At 40 °C it disappears after 25 s.\n\nExplain, in terms of particles, why the reaction is faster at 40 °C.`, marks: 3, command: 'Explain', markScheme: `• Particles have more (kinetic) energy / move faster at 40 °C (1)\n• So collisions are more frequent (1)\n• And a greater proportion of collisions have energy greater than or equal to the activation energy / more collisions are successful (1)\nDo not allow: activation energy is lowered` },
      { q: `Methanol is made in industry from carbon monoxide and hydrogen.\n\nCO(g) + 2H₂(g) ⇌ CH₃OH(g)\n\nThe forward reaction is exothermic.\n\nPredict and explain the effect of increasing the temperature on the yield of methanol.`, marks: 3, command: 'Predict', markScheme: `• The yield of methanol decreases (1)\n• The position of equilibrium moves to the left / in the direction of the backward reaction (1)\n• Because the backward reaction is endothermic, so it takes in the extra heat energy / opposes the change (1)\nDo not allow: reasoning about rate for the second or third mark` },
      { q: `A student plans a titration to find the concentration of dilute sulfuric acid. The student puts 25.0 cm³ of 0.150 mol/dm³ sodium hydroxide solution into a conical flask. The mean titre of sulfuric acid is 18.75 cm³.\n\n2NaOH + H₂SO₄ → Na₂SO₄ + 2H₂O\n\nCalculate the concentration of the sulfuric acid in g/dm³.\n\nRelative atomic masses (Aᵣ): H = 1.0  O = 16.0  S = 32.0`, marks: 4, command: 'Calculate', markScheme: `• Moles of NaOH = 0.150 × (25.0 ÷ 1000) = 0.00375 mol (1)\n• Moles of H₂SO₄ = 0.00375 ÷ 2 = 0.001875 mol (1)\n• Concentration = 0.001875 ÷ (18.75 ÷ 1000) = 0.100 mol/dm³ (1)\n• Mᵣ of H₂SO₄ = 98.0, so concentration = 0.100 × 98.0 = 9.80 g/dm³ (1)\nAward 4 marks for 9.80 / 9.8 g/dm³ with no working.\nECF throughout.\nAllow: 3 marks for 19.6 g/dm³ (2 : 1 ratio not used)` },
      { q: `A student heats 5.00 g of calcium carbonate strongly until it has completely decomposed.\n\nCaCO₃ → CaO + CO₂\n\nThe student collects 2.38 g of calcium oxide.\n\nCalculate the percentage yield of calcium oxide. Give your answer to 3 significant figures.\n\nRelative formula masses (Mᵣ): CaCO₃ = 100.1  CaO = 56.1`, marks: 4, command: 'Calculate', markScheme: `• Moles of CaCO₃ = 5.00 ÷ 100.1 = 0.04995 mol (1)\n• Theoretical mass of CaO = 0.04995 × 56.1 = 2.80 g (1)\n• Percentage yield = (2.38 ÷ 2.80) × 100 (1)\n• = 84.9% (to 3 s.f.) (1)\nAllow: 85.0% if 2.80 is used\nAward 4 marks for 84.9% with no working.\nECF from incorrect theoretical mass.` },
      { q: `Sulfur trioxide is made from sulfur dioxide and oxygen.\n\n2SO₂(g) + O₂(g) ⇌ 2SO₃(g)\n\nThe forward reaction is exothermic. The table shows the percentage of sulfur trioxide in the equilibrium mixture under different conditions (data written for this practice question).\n\nTemperature (°C) | % SO₃ at 1 atm | % SO₃ at 10 atm\n400 | 95 | 98\n500 | 85 | 93\n600 | 65 | 80\n\nDescribe and explain the trends shown by the data.`, marks: 4, command: 'Describe', markScheme: `• As temperature increases, the percentage of SO₃ decreases (1)\n• Because the forward reaction is exothermic, so increasing temperature moves the equilibrium to the left / in the endothermic direction (1)\n• As pressure increases, the percentage of SO₃ increases (1)\n• Because there are fewer gas molecules on the right (2) than on the left (3), so increasing pressure moves the equilibrium to the right (1)\nAllow: quoted data from the table in place of a described trend` },
      { q: `A student wants to investigate how the concentration of hydrochloric acid affects the rate of its reaction with magnesium ribbon.\n\nMg(s) + 2HCl(aq) → MgCl₂(aq) + H₂(g)\n\nThe student has hydrochloric acid of concentrations 0.5, 1.0, 1.5 and 2.0 mol/dm³, magnesium ribbon, a conical flask with a bung and delivery tube, a gas syringe and a stop clock.\n\nDescribe how the student can carry out the investigation and how the results can be used to compare the rates of reaction. Include how the student can make it a fair test.*`, marks: 6, command: 'Describe', markScheme: `Level 3 (5–6 marks)\nGives a clear method that would produce valid results, including control variables, AND explains how the results are processed to compare rates (e.g. initial gradient or mean rate).\nThere is a well-developed line of reasoning which is clear and logically structured. The information presented is relevant and substantiated.\n\nLevel 2 (3–4 marks)\nGives a method that would produce results, with at least one control variable, OR a simple method with some processing of results.\nThere is a line of reasoning presented with some structure. The information presented is relevant and supported by some evidence.\n\nLevel 1 (1–2 marks)\nGives some relevant steps of a method OR identifies variables.\nThere is an attempt at a logical structure with a line of reasoning. The information is in the most part relevant.\n\n0 marks\nNo response or no response worthy of credit.\n\nIndicative scientific points may include:\nMethod\n• Measure a fixed volume of acid (e.g. 25 cm³) with a measuring cylinder into the conical flask\n• Cut a fixed length of magnesium ribbon (e.g. 3 cm)\n• Add the magnesium, put the bung in quickly and start the stop clock\n• Record the volume of gas in the gas syringe at regular intervals (e.g. every 10 s) until no more gas is made\n• Repeat for each concentration, and repeat each concentration to check repeatability\nFair test\n• Same volume of acid\n• Same length / mass / surface area of magnesium\n• Same temperature\n• Same size of flask / same apparatus\nProcessing results\n• Plot volume of gas against time for each concentration\n• Compare the gradient at the start / draw a tangent at t = 0 to find the initial rate\n• OR calculate the mean rate = volume of gas ÷ time taken\n• OR compare the time taken to collect a fixed volume of gas (e.g. 20 cm³)\n• A steeper gradient / shorter time means a faster rate` }
    ]
  },
  'C6': {
    name: 'Global Challenges',
    questions: [
      { q: `This question is about fertilisers.\n\nAmmonium nitrate, NH₄NO₃, is a fertiliser. It is made by reacting ammonia with an acid.\n\nName the acid.`, marks: 1, command: 'Name', markScheme: `Nitric acid (1)\nALLOW HNO₃\nDO NOT ALLOW nitrous acid / sulfuric acid` },
      { q: `Steel buckets and fence wire are often coated with a thin layer of another metal to stop the iron in them from rusting. This is called galvanising.\n\nName the metal used to galvanise steel.`, marks: 1, command: 'Name', markScheme: `Zinc (1)\nALLOW Zn\nDO NOT ALLOW tin` },
      { q: `Crude oil is separated into fractions by fractional distillation. The table shows information about four of the fractions.\n\nFraction | Number of carbon atoms in molecules | Boiling range (°C)\nLPG | 1–4 | below 25\nPetrol | 5–10 | 40–100\nKerosene | 10–16 | 150–250\nDiesel | 14–20 | 220–350\n\nWhich fraction is collected from the top of the fractionating column?`, marks: 1, command: 'State', markScheme: `LPG (1)\nALLOW liquefied petroleum gas / refinery gases` },
      { q: `A student leaves a bottle of wine open to the air for several days. The wine starts to taste sour because the ethanol in it is oxidised.\n\nName the carboxylic acid formed when ethanol is oxidised.`, marks: 1, command: 'Name', markScheme: `Ethanoic acid (1)\nALLOW CH₃COOH\nIGNORE vinegar\nDO NOT ALLOW methanoic acid / ethanol` },
      { q: `Scientists think that the Earth's early atmosphere contained very little oxygen. The percentage of oxygen increased after the first simple plants and algae evolved.\n\nName the process in plants and algae that released oxygen into the atmosphere.`, marks: 1, command: 'Name', markScheme: `Photosynthesis (1)\nDO NOT ALLOW respiration` },
      { q: `Some countries in the Middle East have very little fresh water. They make potable water from seawater by boiling the seawater and condensing the steam.\n\nWhat is the name of this method of making potable water from seawater?`, marks: 1, command: 'Name', markScheme: `Desalination (1)\nALLOW distillation\nIGNORE reverse osmosis` },
      { q: `Copper can be extracted by heating copper oxide with carbon.\n\nThe equation for the reaction is not balanced.\n\n…CuO + C → …Cu + CO₂\n\nBalance the equation and state which substance is reduced.`, marks: 2, command: 'Balance', markScheme: `2CuO + C → 2Cu + CO₂ (1)\nCopper oxide is reduced (1)\nALLOW CuO / copper ions are reduced\nALLOW because it loses oxygen\nDO NOT ALLOW carbon is reduced` },
      { q: `This question is about metals. Part of the reactivity series is shown (most reactive first):\n\npotassium, sodium, aluminium, carbon, zinc, iron, copper\n\nIn a blast furnace, iron is extracted from iron(III) oxide by heating it with carbon.\n\n2Fe₂O₃ + 3C → 4Fe + 3CO₂\n\nExplain why iron can be extracted in this way but aluminium cannot.`, marks: 2, command: 'Explain', markScheme: `Carbon is more reactive than iron so carbon removes oxygen from / reduces iron oxide (1)\nAluminium is more reactive than carbon so carbon cannot reduce aluminium oxide (1)\nALLOW carbon is above iron but below aluminium in the reactivity series for 1 mark only if no reference to reduction / removing oxygen` },
      { q: `Aluminium is extracted by the electrolysis of aluminium oxide. Aluminium oxide has a melting point of 2072 °C. In industry, the aluminium oxide is dissolved in molten cryolite, which lets the electrolysis happen at about 950 °C.\n\nExplain why the aluminium oxide is dissolved in molten cryolite.`, marks: 2, command: 'Explain', markScheme: `Lowers the (melting point / operating) temperature (1)\nSo less energy is needed / reduces (energy) costs (1)\nALLOW so the ions are free to move at a lower temperature for 1 mark\nIGNORE makes it cheaper unqualified` },
      { q: `In the electrolysis of aluminium oxide, both electrodes are made of carbon (graphite). Oxygen is produced at the positive electrode (anode). The anodes have to be replaced regularly.\n\nExplain why the anodes have to be replaced.`, marks: 2, command: 'Explain', markScheme: `Oxygen reacts with the carbon (anode) (1)\nTo form carbon dioxide so the anode wears away / burns away (1)\nALLOW C + O₂ → CO₂ for both marks\nIGNORE anode dissolves / melts` },
      { q: `A student investigates the conditions needed for iron to rust. She sets up three test tubes, each containing an iron nail, and leaves them for one week.\n\nTube A: nail in tap water, open to the air\nTube B: nail in boiled water with a layer of oil on top\nTube C: nail in dry air with anhydrous calcium chloride (a drying agent), stoppered\n\nOnly the nail in tube A rusts.\n\nExplain why the nails in tubes B and C do not rust.`, marks: 2, command: 'Explain', markScheme: `Tube B: no oxygen / air (boiling removes dissolved air and the oil stops air dissolving back in) (1)\nTube C: no water (calcium chloride absorbs the water vapour) (1)\nALLOW idea that rusting needs both oxygen and water if linked to the correct tube` },
      { q: `Ships have steel hulls. Blocks of magnesium are bolted to the hull below the waterline. The steel does not rust while the magnesium blocks are in place, but the blocks have to be replaced every few years.\n\nExplain how the magnesium blocks stop the steel from rusting.`, marks: 2, command: 'Explain', markScheme: `Magnesium is more reactive than iron (1)\nSo magnesium corrodes / is oxidised / loses electrons instead of iron (1)\nALLOW sacrificial protection for the second mark only if linked to magnesium reacting instead of iron\nIGNORE magnesium forms a barrier / coating` },
      { q: `This question is about alloys. The table shows information about some alloys.\n\nAlloy | Main metals in the alloy | Use\nBrass | ………… and zinc | musical instruments\nBronze | copper and ………… | statues and medals\nSolder | tin and silver (lead in older solder) | joining electrical components\n\nComplete the table.`, marks: 2, command: 'Complete', markScheme: `Brass: copper (1)\nBronze: tin (1)\nALLOW Cu and Sn` },
      { q: `Aluminium drinks cans can be recycled. The table shows the energy needed to make 1 tonne of aluminium. (data written for this practice question)\n\nMethod | Energy needed (GJ per tonne)\nExtracting from bauxite ore | 211\nRecycling used cans | 10.5\n\nCalculate the percentage of energy saved by recycling aluminium instead of extracting it from its ore.`, marks: 2, command: 'Calculate', markScheme: `211 − 10.5 = 200.5 (GJ) (1)\n(200.5 ÷ 211) × 100 = 95.0 (%) (1)\nALLOW 95 / 95.02\nALLOW ECF from incorrect energy difference\nALLOW 2 marks for correct answer with no working` },
      { q: `Ammonia, NH₃, is made by the Haber process.\n\nN₂ + 3H₂ ⇌ 2NH₃\n\nState where each of the raw materials, nitrogen and hydrogen, comes from.`, marks: 2, command: 'State', markScheme: `Nitrogen: (fractional distillation of liquid) air (1)\nHydrogen: natural gas / methane (1)\nALLOW from crude oil / cracking for hydrogen\nIGNORE water / electrolysis of water for hydrogen` },
      { q: `In the Haber process, the mixture leaving the reactor is cooled. The ammonia condenses and is removed as a liquid. Only about 15% of the nitrogen and hydrogen are converted into ammonia each time the gases pass over the catalyst.\n\nExplain why the gases that leave the reactor are cooled and what happens to the unreacted nitrogen and hydrogen.`, marks: 2, command: 'Explain', markScheme: `Ammonia has a higher boiling point than nitrogen and hydrogen so it condenses / liquefies and can be separated (1)\nUnreacted nitrogen and hydrogen are recycled / passed back into the reactor, so they are not wasted (1)\nIGNORE to stop the reaction` },
      { q: `Decane is an alkane found in petrol. A molecule of decane has 10 carbon atoms.\n\nAlkanes have the general formula CₙH₂ₙ₊₂.\n\nWrite the molecular formula of decane and explain why decane is described as saturated.`, marks: 2, command: 'Explain', markScheme: `C₁₀H₂₂ (1)\nIt has only (carbon–carbon) single bonds / no C=C double bonds (1)\nDO NOT ALLOW it has no double bonds between carbon and hydrogen` },
      { q: `A student has two unlabelled bottles. One contains hexane, C₆H₁₄. The other contains hexene, C₆H₁₂.\n\nDescribe a chemical test the student could do to find out which bottle contains hexene. Include the result.`, marks: 2, command: 'Describe', markScheme: `Add bromine water / shake with bromine water (1)\nHexene decolourises it / orange to colourless; hexane stays orange (1)\nALLOW yellow / brown / orange-brown for the starting colour\nDO NOT ALLOW clear for colourless\nThe second mark depends on the correct reagent` },
      { q: `Ethanol can be made by reacting ethene with steam. A phosphoric acid catalyst is used.\n\nWrite a balanced symbol equation for this reaction and name the type of reaction.`, marks: 2, command: 'Write', markScheme: `C₂H₄ + H₂O → C₂H₅OH (1)\nALLOW CH₂=CH₂ + H₂O → CH₃CH₂OH\nALLOW ⇌ for →\nAddition / hydration (1)\nDO NOT ALLOW condensation / substitution` },
      { q: `Chloroethene is the monomer used to make PVC, poly(chloroethene). A molecule of chloroethene has a C=C double bond. One carbon atom carries two hydrogen atoms. The other carbon atom carries one hydrogen atom and one chlorine atom.\n\nDraw the displayed formula of the repeating unit of poly(chloroethene).`, marks: 2, command: 'Draw', diagram: true, markScheme: `Two carbon atoms joined by a single bond with three H atoms and one Cl atom attached, all bonds shown (1)\nBrackets drawn through extension bonds on each side, with n (1)\nDO NOT ALLOW a C=C double bond in the repeating unit\nALLOW Cl on either carbon` },
      { q: `Large hydrocarbon molecules from crude oil can be cracked into smaller, more useful molecules.\n\nC₁₆H₃₄ → C₁₀H₂₂ + 2X\n\nWrite the molecular formula of molecule X and name it.`, marks: 2, command: 'Write', markScheme: `C₃H₆ (1)\nPropene (1)\nALLOW ECF for the name of an alkene matching an incorrect formula CₙH₂ₙ` },
      { q: `Crude oil is heated and the vapour is passed into a fractionating column. The column is hot at the bottom and cooler at the top.\n\nExplain how this separates crude oil into fractions.`, marks: 2, command: 'Explain', markScheme: `The hydrocarbons / fractions have different boiling points (1)\nEach fraction condenses at a different height where the temperature is just below its boiling point (1)\nALLOW larger molecules condense lower down / smaller molecules rise higher\nIGNORE melting points` },
      { q: `Carbon dioxide and methane are greenhouse gases. The concentration of carbon dioxide in the atmosphere has increased since the year 1800.\n\nExplain how greenhouse gases keep the Earth warmer than it would otherwise be.`, marks: 2, command: 'Explain', markScheme: `(Visible / short-wave) radiation from the Sun passes through the atmosphere and the Earth's surface gives out / re-emits infrared radiation (1)\nGreenhouse gases absorb (and re-emit) the infrared radiation so it does not escape into space (1)\nALLOW heat for infrared\nDO NOT ALLOW reflect for absorb\nIGNORE references to the ozone layer` },
      { q: `Coal-fired power stations burn coal that contains small amounts of sulfur compounds. This releases sulfur dioxide into the atmosphere.\n\nDescribe how sulfur dioxide damages the environment.`, marks: 2, command: 'Describe', markScheme: `Sulfur dioxide dissolves in rainwater / water in clouds to form acid rain (1)\nAny one effect: damages / kills trees or plants; makes lakes acidic so fish die; corrodes / erodes limestone buildings or statues or metals (1)\nALLOW respiratory problems / asthma for the effect\nIGNORE global warming / climate change` },
      { q: `A gas boiler in a house has a blocked air vent. A carbon monoxide alarm sounds.\n\nExplain why carbon monoxide is produced and why it is dangerous.`, marks: 2, command: 'Explain', markScheme: `Incomplete combustion / not enough oxygen for the fuel to burn completely (1)\nIt is toxic because it combines with haemoglobin / reduces the amount of oxygen the blood can carry (1)\nALLOW it is colourless and odourless so cannot be detected without an alarm, only if toxicity not given\nIGNORE poisonous unqualified for the second mark` },
      { q: `A student adds a spatula of sodium carbonate powder to some dilute ethanoic acid in a test tube.\n\nGive one observation the student would make and name the gas produced.`, marks: 2, command: 'Give', markScheme: `Fizzing / bubbles / effervescence / solid disappears (1)\nCarbon dioxide (1)\nALLOW CO₂\nIGNORE gas given off for the observation` },
      { q: `Some polymers occur naturally in living things. Each one is made from monomers joined together.\n\nPolymer | Monomer\nStarch | glucose / sugars\nProtein | …………\nDNA | …………\n\nComplete the table.`, marks: 2, command: 'Complete', markScheme: `Protein: amino acids (1)\nDNA: nucleotides (1)\nIGNORE bases / sugars / phosphate for DNA` },
      { q: `Scientists think that, about 4000 million years ago, the Earth's atmosphere was mainly carbon dioxide. Today it contains about 0.04% carbon dioxide.\n\nExplain how the percentage of carbon dioxide in the atmosphere decreased.`, marks: 3, command: 'Explain', markScheme: `Any three from:\nCarbon dioxide dissolved in the oceans (as the Earth cooled and water vapour condensed) (1)\nPlants / algae used carbon dioxide in photosynthesis (1)\nCarbon was locked up in sedimentary rocks / limestone / shells of marine organisms (1)\nCarbon was locked up in fossil fuels (coal, crude oil, natural gas) (1)\nIGNORE carbon dioxide escaped into space` },
      { q: `The table shows the mean concentration of carbon dioxide in the atmosphere and the global mean temperature compared with the 1951–1980 average. (temperature data written for this practice question)\n\nYear | CO₂ concentration (ppm) | Temperature difference (°C)\n1960 | 317 | 0.0\n1980 | 339 | +0.3\n2000 | 370 | +0.4\n2020 | 414 | +1.0\n\nA newspaper says: "This proves that carbon dioxide from burning fossil fuels causes global warming."\n\nDescribe the pattern in the data and suggest why scientists would not say the data alone proves this claim.`, marks: 3, command: 'Describe', markScheme: `As CO₂ concentration increases, the temperature difference increases (1)\nCorrelation does not show cause / other factors may affect temperature, e.g. solar activity, volcanic activity (1)\nThe data does not show where the CO₂ came from / only four data points / short time period (1)\nALLOW positive correlation for the first mark\nALLOW the temperature does not increase steadily (e.g. only +0.1 °C between 1980 and 2000)` },
      { q: `Copper ores are running out. Some copper is now extracted from low-grade ores and waste tips using plants. This is called phytoextraction.\n\nDescribe how copper is obtained by phytoextraction and give one advantage of this method.`, marks: 3, command: 'Describe', markScheme: `Plants are grown on the low-grade ore / soil and absorb copper compounds (through their roots) (1)\nThe plants are harvested and burned and copper (compounds) are extracted from the ash (by electrolysis / displacement with scrap iron) (1)\nAdvantage, any one: uses ores that are too low-grade for traditional methods; less mining / less damage to landscape; less energy needed; reduces waste tips / removes toxic metals from land (1)\nIGNORE cheaper unqualified` },
      { q: `A chemical company makes ammonia by the Haber process.\n\nN₂ + 3H₂ ⇌ 2NH₃\n\nIn one test run, 1400 kg of nitrogen reacts with excess hydrogen. Only 255 kg of ammonia is collected.\n\nCalculate the percentage yield of ammonia.\nRelative atomic masses (Aᵣ): H = 1.0  N = 14.0`, marks: 3, command: 'Calculate', markScheme: `Moles of N₂ = 1 400 000 ÷ 28.0 = 50 000 mol (1)\nTheoretical mass of NH₃ = 2 × 50 000 × 17.0 = 1 700 000 g / 1700 kg (1)\nPercentage yield = (255 ÷ 1700) × 100 = 15.0 (%) (1)\nALLOW ratio method: 28 kg N₂ → 34 kg NH₃ so 1400 kg → 1700 kg\nALLOW ECF throughout\nALLOW 3 marks for 15 with no working` },
      { q: `Polyesters are condensation polymers. One polyester is made from two different monomers. One monomer has two –COOH groups. The other monomer has two –OH groups.\n\nExplain how condensation polymerisation is different from addition polymerisation.`, marks: 3, command: 'Explain', markScheme: `Condensation: (usually) two different monomers / monomers with two functional groups; addition: one type of monomer with a C=C bond (1)\nCondensation: a small molecule / water is also produced for each bond formed (1)\nAddition: the polymer is the only product (1)\nALLOW monomers in addition polymerisation must contain a C=C double bond\nALLOW the –COOH and –OH groups react to form ester links` },
      { q: `Propanol, C₃H₇OH, is an alcohol used as a fuel in some camping stoves. It burns completely in oxygen to form carbon dioxide and water.\n\nWrite a balanced symbol equation for the complete combustion of propanol.`, marks: 3, command: 'Write', markScheme: `Correct formulae of products CO₂ and H₂O (1)\nCorrect balancing of carbon and hydrogen, e.g. C₃H₇OH + …O₂ → 3CO₂ + 4H₂O (1)\nFully balanced: 2C₃H₇OH + 9O₂ → 6CO₂ + 8H₂O (1)\nALLOW C₃H₇OH + 4½O₂ → 3CO₂ + 4H₂O\nALLOW multiples` },
      { q: `Water from a reservoir contains leaves, sand, soil particles and microorganisms. It is treated to make it potable (safe to drink).\n\nDescribe how the water is treated to make it potable. Give a reason for each stage.`, marks: 3, command: 'Describe', markScheme: `Sedimentation: large particles / sand / soil settle to the bottom (1)\nFiltration (through beds of sand / gravel): removes small (insoluble) particles (1)\nChlorination: kills microorganisms / bacteria (1)\nALLOW screening / sieving to remove leaves, twigs as an alternative to sedimentation\nDO NOT ALLOW chlorine removes bacteria / filtering removes bacteria` },
      { q: `Pure iron is too soft for many uses. Steel is an alloy of iron with a small amount of carbon. Steel is much harder than pure iron.\n\nExplain why steel is harder than pure iron. Use ideas about particles.`, marks: 3, command: 'Explain', markScheme: `Pure iron has layers of atoms that can slide over each other (easily) (1)\nIn steel, carbon atoms are a different size to iron atoms (1)\nSo the layers are distorted / disrupted and cannot slide (as easily) (1)\nALLOW a labelled diagram for any marking point\nDO NOT ALLOW molecules for atoms` },
      { q: `The table shows the percentage of each fraction obtained from a sample of crude oil and the percentage needed to meet demand. (data written for this practice question)\n\nFraction | Supply (%) | Demand (%)\nLPG | 3 | 4\nPetrol | 12 | 27\nKerosene | 14 | 8\nDiesel | 20 | 23\nFuel oil and bitumen | 51 | 38\n\nOil refineries crack some fractions.\n\nUse the data to explain why cracking is needed and state the conditions used for cracking.`, marks: 3, command: 'Explain', markScheme: `Supply of large-molecule fractions (e.g. fuel oil / bitumen / kerosene) is greater than demand (1)\nCracking turns them into smaller molecules such as petrol, for which demand (27%) is greater than supply (12%) / also makes alkenes for polymers (1)\nConditions: high temperature and a catalyst (1)\nALLOW zeolite / aluminium oxide / silica catalyst\nALLOW about 450–700 °C for high temperature` },
      { q: `Aluminium is extracted by electrolysis of molten aluminium oxide, Al₂O₃, dissolved in cryolite. The aluminium oxide contains Al³⁺ and O²⁻ ions.\n\nWrite the half equations for the reactions at each electrode and calculate the maximum mass of aluminium that can be made from 51 tonnes of aluminium oxide.\nRelative atomic masses (Aᵣ): O = 16.0  Al = 27.0`, marks: 4, command: 'Calculate', markScheme: `Cathode (negative electrode): Al³⁺ + 3e⁻ → Al (1)\nAnode (positive electrode): 2O²⁻ → O₂ + 4e⁻ (1)\nALLOW O²⁻ → ½O₂ + 2e⁻ / 2O²⁻ − 4e⁻ → O₂\nMᵣ of Al₂O₃ = 102, so 102 tonnes Al₂O₃ → 54 tonnes Al (1)\n51 × 54 ÷ 102 = 27 (tonnes) (1)\nALLOW ECF from incorrect Mᵣ\nALLOW 2 marks for 27 tonnes with no working` },
      { q: `The Haber process makes ammonia. The forward reaction is exothermic.\n\nN₂(g) + 3H₂(g) ⇌ 2NH₃(g)\n\nA graph shows the percentage yield of ammonia at equilibrium at 200 atmospheres (data written for this practice question):\n300 °C: 63%   400 °C: 36%   450 °C: 28%   500 °C: 20%\n\nThe conditions used in industry are 450 °C, 200 atmospheres and an iron catalyst.\n\nExplain why these conditions are used even though a higher yield is possible at 300 °C.`, marks: 4, command: 'Explain', markScheme: `Lower temperature gives higher yield because the forward reaction is exothermic / equilibrium shifts in the exothermic direction (1)\nBut at 300 °C the rate is too slow / takes too long to reach equilibrium (1)\nSo 450 °C is a compromise giving an acceptable yield at a fast enough rate (1)\nAny one from (1):\nHigh pressure increases yield because there are fewer moles / molecules of gas on the right (4 → 2)\nHigher pressures than 200 atm are too expensive / dangerous / need stronger equipment\nThe iron catalyst increases the rate without changing the yield, so a lower temperature can be used\nIGNORE catalyst increases yield` },
      { q: `A supermarket compares a life cycle assessment (LCA) of a paper carrier bag and a polythene carrier bag. (data written for this practice question)\n\nStage | Paper bag | Polythene bag\nRaw material | trees (renewable) | crude oil (non-renewable)\nEnergy to make one bag (kJ) | 1680 | 590\nCO₂ released making one bag (g) | 120 | 40\nTimes a bag is reused (mean) | 1 | 4\nDisposal | biodegrades in months; can be recycled | lasts hundreds of years in landfill; can be recycled\n\nCompare the environmental impacts of the two bags. Use the data in the table.`, marks: 4, command: 'Compare', markScheme: `Any four from:\nPaper bag uses a renewable raw material; polythene uses a non-renewable / finite resource (1)\nPaper bag needs about 3 times more energy to make (1680 kJ vs 590 kJ) (1)\nPaper bag releases 3 times more CO₂ when made (120 g vs 40 g) (1)\nPolythene bag is reused more, so the impact per use is even lower (e.g. 10 g CO₂ per use vs 120 g) (1)\nPaper bag biodegrades quickly; polythene bag persists in landfill / can harm wildlife (1)\nBoth can be recycled, which reduces impact (1)\nAn overall judgement supported by data (1)\nMaximum 3 marks if no data from the table are used` },
      { q: `Ammonium sulfate, (NH₄)₂SO₄, is used as a fertiliser. It can be made in a school laboratory and in industry. The table shows information about each method.\n\nLaboratory: dilute ammonia solution and dilute sulfuric acid are bought from a supplier. The acid is titrated with the ammonia solution, then the solution is heated to evaporate some water and left to crystallise. A few grams are made at a time (batch process).\n\nIndustry: ammonia is made from nitrogen (from air) and hydrogen (from natural gas) by the Haber process. Sulfuric acid is made from sulfur, air and water. Ammonia and sulfuric acid are reacted in a large reactor and the product is dried. Thousands of tonnes are made each year, continuously. Heat from exothermic reactions is used elsewhere in the plant.\n\nCompare the laboratory and industrial production of ammonium sulfate.\n\nInclude the reaction involved and the advantages of each method.*`, marks: 6, command: 'Compare', markScheme: `Level 3 (5–6 marks): Compares both methods in detail, covering the reaction AND several clear points of comparison (raw materials, scale, batch vs continuous, conditions / energy) with advantages of each.\nThere is a well-developed line of reasoning which is clear and logically structured. The information presented is relevant and substantiated.\n\nLevel 2 (3–4 marks): Gives the reaction or neutralisation AND some comparison of the two methods, with at least one advantage.\nThere is a line of reasoning presented with some structure. The information presented is in the most part relevant and supported by some evidence.\n\nLevel 1 (1–2 marks): Simple statements about one or both methods, e.g. industry makes more.\nThe information is basic and communicated in an unstructured way.\n\n0 marks: No response or no response worthy of credit.\n\nIndicative scientific points may include:\nReaction\n• Both use neutralisation: 2NH₃ + H₂SO₄ → (NH₄)₂SO₄ / ammonia + sulfuric acid → ammonium sulfate\nRaw materials\n• Lab buys ready-made dilute solutions; industry makes ammonia and sulfuric acid from raw materials (air, natural gas, sulfur, water)\n• Industry is several integrated processes\nScale and process\n• Lab is a small-scale batch process; industry is large scale and continuous\n• Lab uses titration and crystallisation; industry reacts concentrated reactants and dries the solid\nAdvantages of the laboratory method\n• Simple apparatus, cheap to set up, easy to control, can make a pure sample, suitable for small amounts\nAdvantages of the industrial method\n• Makes huge amounts cheaply / low cost per tonne, continuous so efficient, energy from exothermic reactions is reused, does not need to evaporate large volumes of water\nDisadvantages\n• Industry needs high energy / high pressure plant, high set-up cost, uses non-renewable natural gas; lab method is slow and expensive per gram` }
    ]
  }
};

if (typeof module !== 'undefined' && module.exports) module.exports = CHEMISTRY_OCR_A_GCSE_PRACTICE;
